comms.text:
@1 וְצַלֵיתִי קֳדָם יְיָ בְּעִדָנָא הַהִיא לְמֵימָר:
@2 יְיָ אֱלֹהִים אַתְּ שָׁרֵיתָא לְאַחֲזָאָה יָת עַבְדָךְ יָת רְבוּתָךְ וְיָת יְדָךְ תַּקֶפְתָּא דִי אַתְּ הוּא אֱלָהָא דִשְׁכִנְתָּךְ בִּשְׁמַיָא מִלְעֵלָא וְשַׁלִיט בְּאַרְעָא וְלֵית דְיַעְבֵּד כְּעוֹבְדָיךְ וּכְגִבָּרְתָּךְ:
@3 אֵעִבַר כְּעַן וְאֶחֱזֵי יָת אַרְעָא טַבְתָא דִּי בְּעִבְרָא דְיַרְדְנָא טוּרָא טָּבָא הָדֵין וּבֵית מַקְדָשָׁא:
@4 וַהֲוָה רְגַז מִן קֳדָם יְיָ עֲלַי בְּדִילְכוֹן וְלָא קַבִּיל מִנִי וַאֲמַר יְיָ לִי סַגִי לָךְ לָא תוֹסֵף לְמַלָלָא קֳדָמַי עוֹד בְּפִתְגָמָא הָדֵין:
@5 סַק לְרֵישׁ רָמָתָא וּזְקוֹף עֵינָיךְ לְמַעֲרָבָא וּלְצִפּוּנָא וְלִדְרוֹמָא וּלְמָדִינְחָא וַחֲזֵי בְעֵינָיךְ אֲרֵי לָא תְעִבַר יָת יַרְדְנָא הָדֵין:
@6 וּפַקֵד יָת יְהוֹשֻׁעַ וְתַקֶפְהִי וְאַלֶמְהִי אֲרֵי הוּא יֵעִבַר קֳדָם עַמָא הָדֵין וְהוּא יַחְסֵן יָתְהוֹן יָת אַרְעָא דִי תֶחֱזֵי:
@7 וִיתֵבְנָא בְחֵילָתָא לָקֳבֵל בֵּית פְּעוֹר:
@8 וּכְעַן יִשְׂרָאֵל שְׁמַע לִקְיָמַיָא וּלְדִינַיָא דִי אֲנָא מְאַלֵף יָתְכוֹן לְמֶעְבַּד בְּדִיל דְתֵיחוּן וְתֵיתוּן וְתֵירְתוּן יָת אַרְעָא דִי יְיָ אֱלָהָא דַאֲבָהָתְכוֹן יָהֵב לְכוֹן:
@9 לָא תוֹסְפוּן עַל פִּתְגָמָא דִי אֲנָא מְפַקֵד יָתְכוֹן וְלָא תִמְנְעוּן מִנֵהּ לְמִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהֲכוֹן דִי אֲנָא מְפַקֵד יָתְכוֹן:
@10 עֵינֵיכוֹן חָזָן יָת דִי עֲבַד יְיָ בְּבַעַל פְּעוֹר אֲרֵי כָּל גַבְרָא דִי אֲזַל בָּתַר בַּעַל פְּעוֹר שֵׁצְיֵהּ יְיָ אֱלָהָךְ מִבֵּינָךְ:
@11 וְאַתּוּן דְאַדְבֶּקְתּוּן בְּדַחַלְתָּא דַיְיָ אֱלָהֲכוֹן קַיָמִין כֻּלְכוֹן יוֹמָא דֵין:
@12 חֲזוֹ דְאַלֵפִית יָתְכוֹן קְיָמַיָא וְדִינַיָא כְּמָא דִי פַקְדַנִי יְיָ אֱלָהָי לְמֶעְבַּד כֵּן בְּגוֹ אַרְעָא דִי אַתּוּן עַלִין תַּמָן לְמֵירְתַהּ:
@13 וְתִטְרוּן וְתַעְבְּדוּן אֲרֵי הִיא חָכְמַתְכוֹן וְסוּכְלְתָנוּתְכוֹן לְעֵינֵי עַמְמַיָא דִי יִשְׁמְעוּן יָת כָּל קְיָמַיָא הָאִלֵין וְיֵימְרוּן לְחוֹד עַם חַכִּים וְסוּכְלְתָן עַמָא רַבָּא הָדֵין:
@14 אֲרֵי מָן עַם רַב דִי לֵהּ אֱלָהָא קָרִיב לֵהּ לְקַבָּלָא צְלוֹתֵהּ בְּעִדַן עַקְתֵהּ כַּייָ אֱלָהָנָא בְּכָל עִדָן דַאֲנַחְנָא מְצַלִין קֳדָמוֹהִי:
@15 וּמָן עַם רַב דִי לֵהּ קְיָמִין וְדִינִין קַשִׁיטִין כְּכֹל אוֹרַיְתָא הָדָא דִי אֲנָא יָהֵב קֳדָמֵכוֹן יוֹמָא דֵין:
@16 לְחוֹד אִסְתַּמַר לָךְ וְטַר נַפְשָׁךְ לַחֲדָא דִילְמָא תִנְשֵׁי יָת פִּתְגָמַיָא דִי חֲזוֹ עֵינָיִךְ וְדִילְמָא יְעִדוּן מִלִבָּךְ כֹּל יוֹמֵי חַיָיךְ וּתְהוֹדְעִנוּן לִבְנָיךְ וְלִבְנֵי בְנָיִךְ:
@17 יוֹמָא דִי קַמְתָּא קֳדָם יְיָ אֱלָהָךְ בְּחֹרֵב כַּד אֲמַר יְיָ לִי כְּנוֹשׁ קֳדָמַי יָת עַמָא וְאַשְׁמְעִנוּן יָת פִּתְגָמָי דִי יֵלְפוּן לְמִדְחַל קֳדָמַי כָּל יוֹמַיָא דִי אִנוּן קַיָמִין עַל אַרְעָא וְיָת בְּנֵיהוֹן יְאַלְפוּן:
@18 וּקְרֶבְתּוּן וְקַמְתּוּן בְּשִׁפּוֹלֵי טוּרָא וְטוּרָא בָּעֵר בְּאֶשָׁתָא עַד צֵית שְׁמַיָא חֲשׁוֹכָא עֲנָנָא וַאֲמִיטְתָא:
@19 וּמַלִיל יְיָ עִמְכוֹן מִגוֹ אֶשְׁתָא קַל פִּתְגָמִין אַתּוּן שָׁמְעִין וּדְמוּת לֵיתֵיכוֹן חָזָן אֱלָהֵן קָלָא:
@20 וְחַוִי לְכוֹן יָת קְיָמֵהּ דִי פַקִיד יָתְכוֹן לְמֶעְבַּד עַשְׂרָא פִּתְגָמִין וּכְתָבִנוּן עַל תְּרֵין לוּחֵי אַבְנַיָא:
@21 וְיָתִי פַּקִיד יְיָ בְּעִדְנָא הַהִיא לְאַלָפָא יַתְכוֹן קְיָמִין וְדִינִין לְמֶעְבָּדְכוֹן יָתְהוֹן בְּאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@22 וְתִסְתַּמְרוּן לַחֲדָא לְנַפְשָׁתֵיכוֹן אֲרֵי לָא חֲזֵיתוּן כָּל דְמוּת בְּיוֹמָא דִי מַלִיל יְיָ עִמְכוֹן בְּחֹרֵב מִגוֹ אֶשָׁתָא:
@23 דִילְמָא תְּחַבְּלוּן וְתַעְבְּדוּן לְכוֹן צֶלֶם דְמוּת כָּל צוּרָא דְמוּת דְכַר אוֹ נֻקְבָא:
@24 דְמוּת כָּל בְּעִירָא דִי בְאַרְעָא דְמוּת כָּל צִפַּר גַדְפָא דִי פָּרַח בַּאֲוֵר רְקִיע שְׁמַיָא:
@25 דְמוּת כָּל רִחֲשָׁא דִי בְאַרְעָא דְמוּת כָּל נוּנֵי דִי בְמַיָא מִלְרַע לְאַרְעָא:
@26 וְדִילְמָא תִזְקוֹף עֵינָיךְ לִשְׁמַיָא וְתֶחֱזֵי יָת שִׁמְשָׁא וְיָת סִיהֲרָא וְיָת כּוֹכְבַיָא כֹּל חֵילֵי שְׁמַיָא וְתִטְעֵי וְתִסְגוּד לְהוֹן וְתִפְלְחִנוּן דִי זַמִין יְיָ אֱלָהָךְ יָתְהוֹן לְכֹל עַמְמַיָא תְּחוֹת כָּל שְׁמַיָא:
@27 וְיָתְכוֹן קָרִיב יְיָ לְדַחַלְתֵּהּ וְאַפֵּק יָתְכוֹן מִכּוּרָא דְפַרְזְלָא מִמִצְרָיִם לְמֶהֱוֵי לֵהּ לְעַמָא אַחֲסָנָא כְּיוֹמָא הָדֵין:
@28 וּמִן קֳדָם יְיָ הֲוָה רְגַז עֲלַי עַל פִּתְגָמֵיכוֹן וְקַיִים בְּדִיל דְלָא לְמֵעֲבַר יָת יַרְדְנָא וּבְדִיל דְלָא לְמֵיעַל לְאַרְעָא טָבָא דִי יְיָ אֱלָהָךְ יָהֵבּ לָךְ אַחֲסָנָא:
@29 אֲרֵי אֲנָא מָאִית בְּאַרְעָא הָדָא לֵית אֲנָא עָבֵר יָת יַרְדְנָא וְאַתּוּן עָבְרִין וְתֵירְתוּן יָת אַרְעָא טָבָא הָדָא:
@30 אִסְתַּמָרוּ לְכוֹן דִילְמָא תִתְנְשׁוּן יָת קְיָמָא דַיְיָ אֱלָהֲכוֹן דִי גְזַר עִמְכוֹן וְתַעְבְּדוּן לְכוֹן צֶלֶם דְמוּת כֹּלָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@31 אֲרֵי יְיָ אֱלָהָךְ מֵימְרֵהּ אֶשָׁא אָכְלָא הוּא אֵל קַנָא:
@32 אֲרֵי תוֹלְדוּן בְּנִין וּבְנֵי בְנִין וְתִתְעַתְּקוּן בְּאַרְעָא וּתְחַבְּלוּן וְתַעְבְּדוּן צֶלֶם דְמוּת כֹּלָא וְתַעְבְּדוּן דְבִישׁ קֳדָם יְיָ אֱלָהָךְ לְאַרְגָזָא קֳדָמוֹהִי:
@33 אַסְהֵדִית בְּכוֹן יוֹמָא דֵין יָת שְׁמַיָא וְיָת אַרְעָא אֲרֵי מֵיבַד תֵּיבְדוּן בִּפְרִיעַ מֵעַל אַרְעָא דִי אַתּוּן עָבְרִין יָת יַרְדְנָא לְתַמָן לְמֵירְתַהּ לָא תוֹרְכוּן יוֹמִין עֲלַהּ אֲרֵי אִשְׁתְּצָאָה תִּשְׁתֵּצוּן:
@34 וִיבַדַר יְיָ יָתְכוֹן בְּעַמְמַיָא וְתִשְׁתָּאֲרוּן עַם דְמִנְיָן בְּעַמְמַיָא דִי יְדַבַּר יְיָ יָתְכוֹן לְתַמָן:
@35 וְתִפְלְחוּן תַּמָן לְעַמְמַיָא פָלְּחֵי טַעֲוָתָא עֹבַד יְדֵי אֱנָשָׁא אָעָא וְאַבְנָא דִי לָא יֶחֱזוּן וְלָא שָׁמְעִין וְלָא אָכְלִין וְלָא מְרִיחִין:
@36 וְתִתְבְּעוּן מִתַּמָן יָת דַחֲלְתָּא דַייָ אֱלָהָךְ וְתִשְׁכָּח אֲרֵי תִבְעֵי מִן קֳדָמוֹהִי בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@37 כַּד יֵיעוֹק לָךְ וְיַשְׁכְּחֻנָךְ כֹּל פִּתְגָמַיָא הָאִלֵין בְּסוֹף יוֹמַיָא וּתְתוּב לְדַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְקַבֵּל לְמֵימְרֵהּ:
@38 אֲרֵי אֱלָהָא רַחֲמָנָא יְיָ אֱלָהָךְ לָא יִשְׁבְּקִנָךְ וְלָא יְחַבְּלִנָךְ וְלָא יִתִּנְשֵׁי יָת קְיָמָא דַאֲבָהָתָךְ דִי קַיִים לְהוֹן:
@39 אֲרֵי שְׁאֵל כְּעַן לְיוֹמַיָא קַדְמָאֵי דַהֲווֹ קֳדָמָךְ לְמִן יוֹמָא דִי בְרָא יְיָ אָדָם עַל אַרְעָא וּלְמִסְיָפֵי שְׁמַיָא וְעַד סְיָפֵי שְׁמַיָא הַהֲוָה כְּפִתְגָמָא רַבָּא הָדֵין אוֹ הַאִשְׁתְּמַע כְּוָתֵהּ:
@40 הַשְׁמַע עַמָא קַל מֵימְרָא דַיְיָ מְמַלֵל מִגוֹ אֶשָׁתָא כְּמָא דִי שְׁמַעַתְּ אַתְּ וְיִתְקַיָם:
@41 אוֹ נִסִין דִי עֲבַד יְיָ לְאִתְגַלָאָה לְמִפְרַק לֵהּ עַם מִגוֹ עַם בְּנִסִין בְּאָתִין וּבְמוֹפְתִין וּבִקְרָבָא וּבִידָא תַקִיפָא וּבִדְרָעָא מְרָמָא וּבְחֶזְוָנִין רַבְרְבִין כְּכֹל דִי עֲבַד לְכוֹן יְיָ אֱלָהֲכוֹן בְּמִצְרַיִם לְעֵינָיךְ:
@42 אַתְּ אִתְחֲזֵיתָא לְמִדַע אֲרֵי יְיָ הוּא אֱלֹהִים לֵית עוֹד בַּר מִנֵהּ:
@43 מִן שְׁמַיָא אַשְׁמְעָךְ יָת קָל מֵימְרֵהּ לְאַלָפוּתָךְ וְעַל אַרְעָא אַחְזְיָךְ יָת אֶשָׁתֵהּ רַבְּתָא וּפִתְגָמוֹהִי שְׁמַעַתְּ מִגוֹ אֶשָׁתָא:
@44 וָחֳלַף אֲרֵי רְחִים יָת אֲבָהָתָךְ וְאִתִּרְעֵי בִּבְנוֹהִי בַּתְרוֹהִי וְאַפְּקָךְ בְּמֵימְרֵהּ בְּחֵילֵהּ רַבָּא מִמִצְרָיִם:
@45 לְתָרָכָא עַמְמִין רַבְרְבִין וְתַקִיפִין מִנָךְ מִן קֳדָמָךְ לְאָעָלוּתָךְ לְמִתַּן לָךְ יָת אַרְעֲהוֹן אַחֲסָנָא כְּיוֹמָא הָדֵין:
@46 וְתִדַע יוֹמָא דֵין וּתְתוּב לְלִבָּךְ אֲרֵי יְיָ הוּא אֱלָהָא דִשְׁכִנְתֵּהּ בִּשְׁמַיָא מִ לְעֵלָא וְשַׁלִיט עַל אַרְעָא מִלְרָע לֵית עוֹד:
@47 וְתִטַר יָת קְיָמוֹהִי וְיָת פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין דִי יֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ וּבְדִיל דְתוֹרִיךְ יוֹמִין עַל אַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ כָּל יוֹמַיָא:
@48 בְּכֵן יַפְרֵשׁ מֹשֶׁה תְּלַת קִרְוִין בְּעִבְרָא דְיַרְדְנָא מִדְנַח שִׁמְשָׁא:
@49 לְמֵעִירוֹק תַּמָן קָטוֹלָא דִי יִקְטוֹל יָת חַבְרֵהּ בְּלָא מַנְדְעֵי וְהוּא לָא סָנֵי לֵהּ מֵאִתְמַלֵי וּמִדְקַמוֹהִי וְיֵעִרוֹק לְחַד מִן קִרְוַיָא הָאִלֵין וְיִתְקַיָם:
@50 יָת בֶּצֶר בְּמַדְבְּרָא בְּאַרְעָא מֵישְׁרָא לְשִׁבְטָּא דִרְאוּבֵן וְיָת רָאמוֹת בַּגִלְעָד לְשִׁבְטָא דְגָד וְיָת גוֹלָן בְּמַתְנָן לְשִׁבְטָא דִמְנַשֶׁה:
@51 וְדָא אוֹרַיְתָא דִי סַדַר מֹשֶׁה קֳדָם בְּנֵי יִשְׂרָאֵל:
@52 אִלֵין סָהֶדְוָתָא וּקְיָמַיָא וְדִינַיָא דִי מַלִיל מֹשֶׁה עִם בְּנֵי יִשְׂרָאֵל בְּמִפָּקְהוֹן מִמִצְרָיִם:
@53 בְּעִבְרָא דְיַרְדְנָא בְּחֵילָתָא לָקֳבֵל בֵּית פְּעוֹר בְּאַרְעָא דְסִיחֹן מַלְכָּא דֶאֱמֹרָאָה דִי יָתֵב בְּחֶשְׁבּוֹן דִי מְחָא מֹשֶׁה וּבְנֵי יִשְׂרָאֵל בְּמִפָּקְהוֹן מִמִצְרָיִם:
@54 וִירִיתוּ יָת אַרְעֵהּ וְיָת אַרְעָא דְעוֹג מַלְכָּא דְמַתְנָן תְּרֵין מַלְכֵי אֱמֹרָאָה דִי בְּעִבְרָא דְיַרְדְנָא מִדְנַח שִׁמְשָׁא:
@55 מֵעֲרֹעֵר דִי עַל כֵּיף נַחֲלָא דְאַרְנֹן וְעַד טוּרָא דְשִׂיאֹן הוּא חֶרְמוֹן:
@56 וְכָל מֵישְׁרָא עִבְרָא דְיַרְדְנָא לְמָדִינְחָא וְעַד יַמָא דְמֵישְׁרָא תְּחוֹת מַשְׁפַּךְ מְרָמָתָא:
@57 וּקְרָא מֹשֶׁה לְכָל יִשְׂרָאֵל וַאֲמַר לְהוֹן שְׁמַע יִשְׂרָאֵל יָת קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא מְמַלֵל קֳדָמֵיכוֹן יוֹמָא דֵין וְתַלְפוּן יָתְהוֹן וְתִטְרוּן לְמֶעְבָּדְהוֹן:
@58 יְיָ אֱלָהָנָא גְזַר עִמָנָא קְיָם בְּחֹרֵב:
@59 לָא עִם אֲבְהָתָנָא גְזַר יְיָ יָת קְיָמָא הָדָא אֶלָהֵן עִמָנָא אֲנַחְנָא אִלֵין הָכָא יוֹמָא דֵין כֻּלָנָא קַיָמִין:
@60 מַמְלָל עִם מַמְלָל מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא:
@61 אֲנָא הֲוֵיתִי קָאֵם בֵּין מֵימְרָא דַיְיָ וּבֵינֵיכוֹן בְּעִדָנָא הַהִיא לְחַוָאָה לְכוֹן יָת פִּתְגָמָא דַיְיָ אֲרֵי דְחֶלְתּוּן מִקֳדָם אֵשָׁתָא וְלָא סְלֶקְתּוּן בְּטוּרָא לְמֵימָר:
@62 אֲנָא יְיָ אֱלָהָךְ דִי אַפֵּקְתָּךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עֲבְדוּתָא:
@63 לָא יְהֵא לָךְ אֱלָהּ אָחָרָן בַּר מִנִי:
@64 לָא תַעְבֵּד לָךְ צֶלֶם כָּל דְמוּת דִי בִשְׁמַיָא מִלְעֵלָא וְדִי בְאַרְעָא מִלְרָע וְדִי בְמַיָא מִלְרַע לְאַרְעָא:
@65 לָא תִסְגוּד לְהוֹן וְלָא תִפְלְחִנוּן אֲרֵי אֲנָא יְיָ אֱלָהָךְ אֵל קַנָא מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין מְרָדִין עַל דַר תְּלִיתַי וְעַל דַר רְבִיעַי לְשַׂנְאָי כַּד מְשַׁלְמִין בְּנַיָא לְמֶחֱטֵּי בָּתַר אֲבָהָתְהוֹן:
@66 וְעָבֵד טֵּיבוּ לְאַלְפֵי דָרִין לְרַחֲמַי וּלְנָטְּרֵי פִקוֹדָי:
@67 לָא תֵימֵי בִּשְׁמָא דַיְיָ אֱלָהָךְ לְמַגָנָא אֲרֵי לָא יְזַכֵּי יְיָ יָת דִי יֵמֵי בִשְׁמֵהּ לְשִׁקְרָא:
@68 טַר יָת יוֹמָא דְשַׁבְּתָא לְקַדָשׁוּתֵהּ כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@69 שִׁתָּא יוֹמִין תִּפְלָח וְתַעְבֵּד כָּל עִבִדְתָּךְ:
@70 וְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד כָּל עֲבִידָא אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְתוֹרָךְ וַחֲמָרָךְ וְכָל בְּעִירָךְ וְגִיוֹרָךְ דִי בְקִרְוָךְ בְּדִיל דִי יְנוּחַ עַבְדָךְ וְאַמְתָךְ כְּוָתָךְ:
@71 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרַיִם וְאַפְּקָךְ יְיָ אֱלָהָךְ מִתַּמָן בִּידָא תַקִיפָא וּבִדְרָעָא מְרָמְמָא עַל כֵּן פַּקְדָךְ יְיָ אֱלָהָךְ לְמֶעְבַּד יָת יוֹמָא דְשַׁבְּתָא:
@72 יַקַר יָת אֲבוּךְ וְיָת אִמָךְ כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ וּבְדִיל דְיֵיטַב לָךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@73 לָא תִקְטוֹל נְפָשׁ וְלָא תְגוּף וְלָא תִגְנוֹב (נַפְשָׁא) וְלָא תַסְהֵד בְּחַבְרָךְ סַהֲדוּתָא דְשִׁקְרָא:
@74 וְלָא תַחְמֵד אִתַּת חַבְרָךְ וְלָא תֵרוֹג בֵּית חַבְרָךְ חַקְלֵהּ וְעַבְדֵהּ וְאַמְתֵהּ תּוֹרֵה וַחֲמָרֵהּ וְכֹל דִי לְחַבְרָךְ:
@75 יָת פִּתְגָמַיָא הָאִלֵין מַלִיל יְיָ עִם כָּל קְהָלְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא עֲנָנָא וַאֲמִיטְתָא קָל רַב וְלָא פְסַק וּכְתָבִנוּן עַל תְּרֵין לוּחֵי אַבְנַיָא וִיהָבִנָן לִי:
@76 וַהֲוָה כַּד שְׁמַעֲכוֹן יָת קָלָא מִגוֹ חֲשׁוֹכָא וְטוּרָא בָּעֵר בְּאֶשָׁתָא וְקָרֶבְתּוּן לְוָתִי כָּל רֵישֵׁי שִׁבְטֵיכוֹן וְסָבֵיכוֹן:
@77 וַאֲמַרְתּוּן הָא אַחְזְיָנָא יְיָ אֱלָהָנָא יָת יְקָרֵהּ וְיָת רְבוּתֵהּ וְיָת קָל מֵימְרֵהּ שְׁמַעְנָא מִגוֹ אֶשָׁתָא יוֹמָא הָדֵין חֲזֵינָא אֲרֵי יְמַלֵל יְיָ עִם אֲנָשָׁא וְיִתְקַיָם:
@78 וּכְעַן לְמָא נְמוּת אֲרֵי תֵיכְלִנָנָא אֶשָׁתָא רַבְּתָא הָדָא אִם מוֹסְפִין אֲנַחְנָא לְמִשְׁמַע יָת קָל מֵימְרָא דַייָ אֱלָהָנָא עוֹד וּמָיְתִין אֲנַחְנָא:
@79 אֲרֵי מָן כָּל בִּשְׂרָא דִי שְׁמַע קָל מֵימְרָא דַיְיָ קַיָמָא מְמַלֵל מִגוֹ אֶשָׁתָא כְּוָתָנָא וְאִתְקַיָם:
@80 קְרַב אַתְּ וּשְׁמַע יָת כָּל דִי יֵימַר יְיָ אֱלָהָנָא וְאַתְּ תְּמַלֵל עִמָנָא יָת כָּל דִי מַלֵל יְיָ אֱלָהָנָא עִמָךְ וּנְקַבֵּל וְנַעְבֵּד:
@81 וּשְׁמִיעַ קֳדָם יְיָ יָת קָל פִּתְגָמֵיכוֹן בְּמַלָלוּתְכוֹן עִמִי וַאֲמַר יְיָ לִי שְׁמִיעַ קֳדָמַי יָת קָל פִּתְגָמֵי עַמָא הָדֵין דִי מַלִילוּ עִמָךְ אַתְקִינוּ כָּל דִי מַלִילוּ:
@82 לְוַי דִי יְהֵי לִבָּא הָדֵין לְהוֹן לְמִדְחַל קֳדָמַי וּלְמִטַר יָת כָּל פִּקוּדַי כָּל יוֹמַיָא בְּדִיל דִיֵיטַב לְהוֹן וְלִבְנֵיהוֹן לְעָלָם:
@83 אִזֵל אֱמַר לְהוֹן תּוּבוּ לְכוֹן לְמַשְׁכְּנֵיכוֹן:
@84 וְאַתְּ הָכָא קִים קֳדָמַי וֶאֱמַלֵל עִמָךְ יָת כָּלּ תַּפְקֶדְתָּא וּקְיָמַיָא וְדִינַיָא דִי תַלְפִנוּן וְיַעְבְּדוּן בְּאַרְעָא דִי אֲנָא יָהֵב לְהוֹן לְמֵירְתַהּ:
@85 וְתִטְרוּן לְמֶעְבַּד כְּמָא דִי פַקִיד יְיָ אֱלָהֲכוֹן יָתְכוֹן לָא תִסְטוּן יַמִינָא וּשְׂמָאלָא:
@86 בְּכָל אָרְחָא דִי פַקִיד יְיָ אֱלָהֲכוֹן יָתְכוֹן תְּהָכוּן בְּדִיל דְתֵיחוּן וְיֵיטַב לְכוֹן וְתוֹרְכוּן יוֹמִין בְּאַרְעָא דִי תֵירְתוּן:
@87 וְדָא תַפְקֶדְתָּא קְיָמַיָא וְדִינַיָא דִי פַקִיד יְיָ אֱלָהֲכוֹן לְאַלָפָא יָתְכוֹן לְמֶעְבַּד בְּאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@88 בְּדִיל דְתִדְחַל קֳדָם יְיָ אֱלָהָךְ לְמִטַר יָת כָּל קְיָמוֹהִי וּפִקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ אַתְּ וּבְרָךְ וּבַר בְּרָךְ כָּל יוֹמֵי חַיָיךְ וּבְדִיל דְיוֹרְכוּן יוֹמָיךְ:
@89 וּתְקַבֵּל יִשְׂרָאֵל וְתִטַר לְמֶעְבַּד דִי יֵיטַב לָךְ וְדִי תִסְגוּן לַחֲדָא כְּמָא דִי מַלִיל יְיָ אֱלָהָא דַאֲבָהָתָךְ לָךְ אַרְעָא עָבְדָא חֲלַב וּדְבָשׁ:
@90 שְׁמַע יִשְׂרָאֵל יְיָ אֱלָהָנָא יְיָ חָד:
@91 וְתִרְחַם יָת יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ וּבְכָל נִכְסָךְ:
@92 וִיהוֹן פִּתְגָמַיָא הָאִלֵין דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין עַל לִבָּךְ:
@93 וּתְתָנִנוּן לִבְנָיךְ וּתְמַלֵל בְּהוֹן בְּמִתְּבָךְ בְּבֵיתָךְ וּבִמְהָכָךְ בְּאָרְחָא וּבְמִשְׁכְּבָךְ וּבִמְקִימָךְ:
@94 וְתִקְטְרִנוּן לְאָת עַל יְדָךְ וִיהוֹן לִתְפִלִין בֵּין עֵינָיךְ:
@95 וְתִכְתְּבִנוּן עַל מְזוּזְיָן וְתִקְבְּעִנוּן בְּסִפֵּי בֵיתָךְ וּבְתַרְעָיךְ:
@96 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי קַיִים לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לָךְ קִרְוִין רַבְרְבָן וְטָבָן דִי לָא בְנֵיתָא:
@97 וּבָתִּין מְלָן כָּל טוּב דִי לָא מְלֵיתָא וְגֻבִּין פְּסִילָן דִי לָא פְּסַלְתָּא כַּרְמִין וְזֵיתִין דִי לָא נְצֶבְתָּא וְתֵיכוּל וְתִשְׂבָּע:
@98 אִסְתַּמַר לָךְ דִילְמָא תִנְשֵׁי יָת (דַחַלְתָּא דַ) יְיָ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@99 יָת יְיָ אֱלָהָךְ תִּדְחַל וְקָדָמוֹהִי תִּפְלָח וּבִשְׁמֵהּ תְּקַיַם:
@100 לָא תְהָכוּן בָּתַר טַעֲוַת עַמְמַיָא מִטַעֲוַת עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן:
@101 אֲרֵי אֵל קַנָא יְיָ אֱלָהָךְ שְׁכִנְתֵּהּ בֵּינָךְ דִילְמָא יִתְקֵף רָגְזָא דַיְיָ אֱלָהָךְ בָּךְ וִישֵׁצָךְ מֵעַל אַפֵּי אַרְעָא:
@102 לָא תְנַסוּן קֳדָם יְיָ אֱלָהֲכוֹן כְּמָא דִי נַסֵתוּן בְנִסֵיתָא:
@103 מִטַּר תִּטְרוּן יָת פִּקוּדַיָא דַיְיָ אֱלָהֲכוֹן וּסְהֶדְוָתֵהּ וּקְיָמוֹהִי דִי פַקְדָךְ:
@104 וְתַעְבֵּד דְכָשַׁר וּדְתַקֵן קֳדָם יְיָ בְּדִיל דְיֵיטַב לָךְ וְתֵעוּל וְתֵירַת יָת אַרְעָא טַבְתָא דִי קַיִים יְיָ לַאֲבָהָתָךְ:
@105 לְמִתְּבַר יָת כָּל בַּעֲלֵי דְבָבָךְ מֵקָדָמָךְ כְּמָא דִי מַלִיל יְיָ:
@106 אֲרֵי יִשְׁאֲלִנָךְ בְּרָךְ מְחָר לְמֵימָר מָא סָהֶדְוָתָא וּקְיָמַיָא וְדִינַיָא דִי פַקִיד יְיָ אֱלָהָנָא יָתְכוֹן:
@107 וְתֵימַר לִבְרָךְ עַבְדִין הֲוֵינָא לְפַרְעֹה בְּמִצְרָיִם וְאַפְּקָנָא יְיָ מִמִצְרַיִם בִּידָא תַקִיפָא:
@108 וִיהַב יְיָ אָתִין וּמוֹפְתִין רַבְרְבִין וּבִישִׁין בְּמִצְרַיִם בְּפַרְעֹה וּבְכָל אֱנַשׁ בֵּיתֵהּ לְעֵינָנָא:
@109 וְיָתָנָא אַפֵּק מִתַּמָן בְּדִיל לְאַעֲלָא יָתָנָא לְמִתַּן לָנָא יָת אַרְעָא דִי קַיִים לַאֲבָהָתָנָא:
@110 וּפַּקְדָנָא יְיָ לְמֶעְבַּד יָת כָּל קְיָמַיָא הָאִלֵין לְמִדְחַל יָת יְיָ אֱלָהָנָא לְטַב לָנָא כָּל יוֹמַיָא לְקַיָמוּתָנָא כְּיוֹמָא הָדֵין:
@111 וְזָכוּתָא תְּהֵא לָנָא אֲרֵי נִטַר לְמֶעְבַּד יָת כָּל תַּפְקֶדְתָּא הָדָא קֳדָם יְיָ אֱלָהָנָא כְּמָא דִי פַקְדָנָא:
@112 אֲרֵי יְעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ וִיתָרֵךְ עַמְמִין סַגִיאִין מִן קֳדָמָךְ חִתָּאֵי וְגִרְגָשָׁאֵי וֶאֱמֹרָאֵי וּכְנַעֲנָאֵי וּפְרִזָאֵי וְחִוָאֵי וִיבוּסָאֵי שִׁבְעָא עַמְמִין סַגִיאִין וְתַקִיפִין מִנָךְ:
@113 וְיִמְסְרִנוּן יְיָ אֱלָהָךְ קֳדָמָךְ וְתִמְחִנוּן גַמָרָא תְגַמַר יָתְהוֹן לָא תִגְזַר לְהוֹן קְיָם וְלָא תְרַחַם עֲלֵיהוֹן:
@114 וְלָא תִתְחַתַּן בְּהוֹן בְּרַתָּךְ לָא תִתֵּן לִבְרֵהּ וּבְרַתֵּהּ לָא תִסַב לִבְרָךְ:
@115 אֲרֵי יַטְעֲיַן יָת בְּרָךְ מִבָּתַר פָּלְחָנִי וְיִפְלְחוּן לְטַעֲוַת עַמְמַיָא וְיִתְקֵף רָגְזָא דַיְיָ בְּכוֹן וִישֵׁצָךְ בִּפְרִיעַ:
@116 אֲרֵי אִם כְּדֵין תַּעַבְּדוּן לְהוֹן אֱגוֹרֵיהוֹן תְּתָרְעוּן וְקָמָתְהוֹן תְּתַבְּרוּן וַאֲשֵׁרֵיהוֹן תְּקוֹצְצוּן וְצַלְמֵי טַּעֲוָתְהוֹן תּוֹקְדוּן בְּנוּרָא:
@117 אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ בָּךְ אִתִּרְעֵי יְיָ אֱלָהָךְ לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב מִכֹּל עַמְמַיָא דִי עַל אַפֵּי אַרְעָא:
@118 לָא מִדְסַגִיאִין אַתּוּן מִכָּל עַמְמַיָא צָבֵי יְיָ בְּכוֹן וְאִתִּרְעֵי בְכוֹן אֲרֵי אַתּוּן זְעֵרִין מִכָּל עַמְמַיָא:
@119 אֲרֵי מִדְרַחַם יְיָ יָתְכוֹן וּמִדִנְטַר יָת קְיָמָא דִי קַיִים לַאֲבָהָתְכוֹן אַפֵּיק יְיָ יָתְכוֹן בִּידָא תַקִיפָא וּפָרְקָךְ מִבֵּית עַבְדוּתָא מִידָא דְפַרְעֹה מַלְכָּא דְמִצְרָיִם:
@120 וְתִדַע אֲרֵי יְיָ אֱלָהָךְ הוּא אֱלֹהִים אֱלָהָא מְהֵימְנָא נָטֵר קְיָמָא וְחִסְדָא לְרַחֲמוֹהִי וּלְנָטְרֵי פִקוֹדוֹהִי לְאַלְפֵי דָרִין:
@121 וּמְשַׁלֵם לְסָנְאוֹהִי טָבָן דִי אִנוּן עָבְדִין קֳדָמוֹהִי בְּחַיֵיהוֹן לְאוֹבָדֵיהוֹן לָא מְאַחַר עֹבַד טָב לְסָנְאוֹהִי טַבְוָן דִי אִנוּן עָבְדִין קָדָמוֹהִי בְּחַיֵיהוֹן מְשַׁלֵם לְהוֹן:
@122 וְתִטַר יָת תַּפְקֶדְתָּא וְיָת קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמֶעְבָּדְהוֹן: פפפ:

@1 **ואתחנן אל ה' בעת ההיא לאמר**. צריך לדעת אומרו **בעת ההיא**, ורבותינו ז''ל אמרו (ספרי) כשראה שנפל סיחון ועוג לפניו וכו', לדבריהם חוזר למה שלפניו שהיא מלחמת סיחון ועוג, ולפי זה טעם המאמר לומר שזולת מה שהיה בעת ההיא לא הייתי מתפלל כי הגזירה כבר נגזרה:
@1 **ונראה** לומר בהעיר עוד אמרו **לאמר**, ורבותינו ז''ל דרשו (שם) שאמר משה לה' השיבני על דברי אם אני נכנס לארץ, וזה דרך דרש, אכן פירוש אומרו בעת ההיא הוא זמן שנשבע ה' על דור המדבר שלא יראו את הארץ שאמר בפרשה שלמעלה וכללו למשה בכלל שבועת הגזירה כמו שאמר (א' ל''ז) גם בי התאנף ה' בגללכם, בעת ההיא התחנן לה' לבטל גזירתו ולהתיר השבועה כרמוז במאמר אתה החלות ודרשו רבותינו ז''ל לשון התרת שבועה כאשר אבאר בסמוך, וטעם המאמר הוא להודיעם לבל יחשדהו שלא התפלל אלא על עצמו לבטל גזירתו ולא חש לדורו והעלים עין ממנו ותם כל הדור ההוא, לזה אמר **בעת ההיא** פירוש קודם שנתקיימה הגזירה התחנן לה':
@1 **והגם** שבתחילתו לא מצינו שלא הזכיר אלא על עצמו ולא עמו, אף על פי כן כונתו היתה בחכמה שהתפלל על עצמו להתיר שבועה שעליו ואחר כך יאמר לפניו לבטל גם על ישראל, ויהיה הדבר קל להשיג מדין נדר שהותר מקצתו הותר כלו (נדרים סו.), והוא אומרו **לאמר** פירוש אין תכלית הדבר בדברים הנאמרים אלא לאמר עוד דברים אחרים, וזה עשה בחכמה כי יותר יהיה נקל להתקבל תפלתו על עצמו להתיר שבועת הגזירה שעליו להיותו נקי וצדיק מהתיר שבועת גזירת ישראל שהם בעלי העון, וכל דברי משה יגידו צדקת ה' עשה:
@1 **עוד** נתכוון לדייק ד' תנאים הצריכין לקבלת תפלה, אחד שיתפלל כעני הדופק על הפתח כדרך אומרו (משלי י''ח) תחנונים ידבר רש, ב' שיבקש ממקור הרחמים, ג' זמן התפלה כדרך אומרו (תהלים ס''ט) ואני תפלתי לך ה' עת רצון, ד' שתהיה תפלתו מפורשת ולא תהיה סובלת פירוש בלתי הגון, וכמעשה שהובא במדרש (אסתר ר' פ''ז כ''ד) בההוא גוי וישראל וכו' וילדה בהמתו של גוי ואנס ישראל להרכיבו על כתפו וכו' ע''כ, והוא מה שנתכוון משה במאמרו כאן **ואתחנן** ל' תחנונים זה כנגד תנאי א', **אל ה'** שבקש ממקור הרחמים זה כנגד תנאי ב', **בעת ההיא** פירוש בעת הידועה לקבלת תפלה שהיא עת רצון כי מי יודע עת הרצון כמשה, ואפשר שזה היה בעת אשר אמר לו ה' החל רש ארץ סיחון ועוג, וזה מכוון לדברי רבותינו ז''ל שאמרו לאחר. שכבש ארץ סיחון ועוג וכו' זה כנגד תנאי ג', **לאמר** פירוש פירש אמריו כמצטרך שלא יסבלו דבריו דבר בלתי הגון זה כנגד תנאי ד', ולדברי רבותינו ז''ל שאמרו בעת ההיא כשראה מלחמת סיחון ועוג, טעם אומרו **לאמר**, נמשכת עם אתה החילות, וכבר כתבתי בכמה מקומות כי כשאינו אומר הדיבור בלשון עצמו שאמרו אלא כולל המכוון בלשון אחר הוא אומר לאמר פירוש כונת המאמר היא זאת, כמו כן במה שלפנינו אמר לאמר להעירך על זה, ויש מרבותינו ז''ל שאמרו (. לק, יט) בעת ההיא כשאמר לו (במרבר כ' י''ב) לא תביאו את הקהל וגו', ויש שאמרו (רבה) כשאמר לו (במדבר כ''ז י''ח) קח את יהושע וגו', ואפשר שבכל העתים התפלל ועל כל עת מהם הוא אומר בעת ההיא, ואלו ואלו דברי אלהים חיים:
@2 **אדני אלוהים**. אומרו **אדני**, על דרך מה שאמר עלי (ש''א ג') אדני הוא הטוב בעיניו יעשה, פירוש שהפסד העבד והצלחתו היא נוגעת לאדונו וכיון שכן הטוב בעיניו יעשה ודאי, והוא אומרו אדני פירוש הצלחתי וטובתי לך הוא, ואומרו הוי''ה בניקוד אלהים, רש''י ז''ל פירוש וז''ל אדני אלהים רחום בדין ע''כ, וראיתי לרמב''ן שכתב על דבריו וז''ל ולא השגיח הרב כי השם הראשון כתוב באל''ף דל''ת והשני כתוב ביו''ד ה''א וכו' ע''כ, ואני אומר שלא נתכוון רש''י על שם אדנות אלא על שם הויה שהוא כתוב הוי''ה ונקוד בניקוד אלהים, וכך הם דברי המדרש (ספרי) וז''ל הוי''ה רחמים אלהים דין ע''כ, פירוש הכתיבה שהיא הוי''ה רחמים הקריאה שהיא אלהים דין, ובזה אין כאן השגה:
@2 **וטעם** שאמר שם זה שבו רחמים ודין לפי מה שפירשתי באומרו לאמר שנתכוון בתפלתו לומר גם על ישראל לזה אמר דין ורחמים, דין למה שנוגע אל ביטול גזרת משה כאומרם ז''ל (תנחומא) משל למלך שביקש לישא אשה שלח שלוחין לראותה הלכו וכו' באו ואמרו לו אין כעורה ממנה שמע השושבין אמר לו מרי אין נאה ממנה בעולם בא לישא אותה אמר אבי הנערה לשלוחי המלך נשבע אני שאין אחד מכם נכנס כיון שבזיתם אותה בא שושבין לכנס א''ל אף אתה לא תכנס אמר לו השושבין אני לא ראיתיה ואף על פי כן אמרתי למלך אין נאה הימנה וכו' כך אמר משה לפני ה' וכו' ע''כ, הרי כי בטענה חזקה בא לומר ששורת הדין נותנת כי עלה יעלה אל הארץ, והוא מה שנתכוון בזכרון שם אלהים, ורמז בכתיבה שם הרחמים למה שנוגע לביטול הגזירה מעל ישראל כמו שפירשתי בתיבת לאמר, ונתחכם להזכיר שם הדין לפי שבנגלה לא התפלל אלא על עצמו, ורמז שם הרחמים בנסתר לפי שתפלת ישראל היתה בנסתר אצלו בכח אחר שיהיה נענה בשביל עצמו:
@2 **עוד** אפשר כי לצד שבא בטענה לזכות כפי הדין הוכרח לשתף מדת הרחמים כי מי זה יצטדק לפני מלך עולם בטוען ונטען וכתיב (תהלים קמ''ג) כי לא יצדק לפניך כל חי, לזה מתק הדין במדת הרחמים:
@2 **אתה החילות וגו'**. תיבת החילות פירשו רבותינו ז''ל בספרי בשלשה דרכים, לשון התחלה, ולשון תפלה על דרך אומרו (מלאכי א') חלו נא פני אל, ולשון התרה, וז''ל ספרי אתה החילות אתה התרת נדרי בשעה שאמרת לי (שמות ג' י') הוצא את עמי וגו' ואמרתי לך כבר נשבעתי ליתרו וגו', דבר אחר אתה פתחת לי פתח להתפלל שאמרת לי הדף ממני וגומר וכי תפוס הייתי בך וכו', וכפי זה מפרש החילות לשון תפלה, ד''א התחלת פתח בשעה שנכנסתי לנחלות בני גד ובני ראובן ע''כ, קשה בשלמא טענת התחלת וגם טענת אתה פתחת לי להתפלל הם דברי טעם לתפלה, אבל טענת פתח ההתרה מה ראיה מביא ממה שהתיר לו שבועתו ליתרו שאני שבועת יתרו שהיה לה פתח וישנה בהתרה, והפתח הוא שבא אליו דבר מלך שלטון ללכת בשליחותו ואין לך פתח גדול מזה, מה שאין כן שבועתו יתברך אין צודק בה פתח שכל הפתחים גלוי וצפוי לפניו והוא מגיד מראשית אחרית:
@2 **ויתבאר** על פי מה שכתב רמב''ם בפ''ו מהלכות שבועות וז''ל מי שנשבע ולא ניחם ובא לקיים שבועתו אם ראו ב''ד שהתר שבועה זו מקיום מצוה או שלום בין אדם לחבירו וכו' בית דין נושאים ונותנים עמו עד שיתנחם וכו' ומתירים לו ע''כ, ומשמע שהגם שאין פתח זו אצלו פתח אף על פי כן מתחכמין עליו להתחרט, והוא מה שנתכוון משה בטענתו לפני ה' **אתה החילות** שהוא התיר לו שבועתו כשנשבע ליתרו הגם שלא היה חפץ להתיר, והראיה ששבעת ימים ה' אמר לו (שמות ג' י') לכה ואשלחך אל פרעה והוא לא היה רוצה מאיזה טעם שיהיה ונשא ונתן ה' עמו עד שנתרצה לדבר מצוה והלך והתיר נדרו, וכמו כן יתיר ה' שבועת גזירת משה, והגם שאין כאן פתח יש כאן דבר מצוה להראותו את הארץ הטובה כאומרו אעברה נא ואראה וגו', ואם תאמר מה דמיון דין שכתב רמב''ם לשאלת משה, כי דין רמב''ם המתיר הוא המקיים המצוה ולזה מתירין לו, אבל מה שלפנינו ה' נשבע ובהתרתו משה הוא שעושה מצות הליכת הארץ, לזה דקדק משה בדבריו ואמר **את עבדך** וידוע כי מה שקנה עבד קנה רבו:
@3 **אעברה נא ואראה וגו'**. צריך לדעת כוונת אומרו **נא**, גם למה הוצרך לומר **ואראה** וגו' הלא כשיעבור הענין מעצמו מובן שיראה וכו', ואולי שנתכוין להשיב תשובה על הדברים המונעים ביאתו לארץ כאומרם ז''ל שהם ב', א' לפי שהגיע זמנו של יהושע למלוך (תנחומא) ואין מלכות נוגעת בחברתה אפילו כמלא נימא, ב' שצפה הקב''ה שעתידין ישראל לחטוא ויצטרך להשליך חמתו עליהם וחשב ה' למשכן בשבילם הבית המקודש כרמוז בתיבת משכן משכן כאומרם ז''ל (שמו''ר פנ''א), ובזה יש תקוה ותכלית טוב לישראל וכמאמרם ז''ל (מדרש תהלים ע''ט) בפסוק מזמור לאסף אלהים באו גוים וגו' מזמור קינה מבעי ליה אלא שהשליך חמתו על עצים ואבנים ולא השליכה על ישראל וכו' ע''כ, ואם היה משה בונה בית המקדש אמרו ז''ל (סוטה ט'.) שלא היתה אומה ולשון שולטת בו וזה יסובב לשפוך חמתו עליהם לכלותם, וכמו שפירשתי בפרשת דברים בפסוק (א' ל''ז) גם בי התאנף:
@3 **לזה** נתכוון משה בדבריו להשיג על ב' דברים אלו, כנגד המלכות שאינה נוגעת וכו' אמר **אעברה נא** פירוש אעברה כדרך העוברים שלא בדרך שררה וכבוד, וכנגד מיחוש עם בני ישראל כדי שיהיה להם בית המקדש לפדיון נפשם אמר **ואראה** פירוש לא לבנות אלא לראות לבד, ובזה הוסרו ב' המיחושים, ודקדק לו' תיבת **נא** פירוש הן עתה יעבור ממלכותו כדי להשיג תקוה זו:
@3 **עוד** נתכוון לבקש שימהר לעבור כל עוד שיש שהות ביום שעדיין לא כלו לו ימיו, ולמה שכתבתי בפירוש בעת ההיא שנתכוון אל זמן הגזירה של המרגלים, נתכוון לומר שממהר לעבור בזמן זה שעדיין ימיו רבים, ומתוך הדברים תשכיל שנתכוון לבטל גזרת ישראל, כי גזרתם היתה שימותו במדבר ולא ימותו מיתת כרת עד שיהיו כלם בני ס' שנה, ואם יכנס משה אז הדבר מובן מעצמו שיכנסו כל ישראל שלא גזר ה' עליהם שימותו מיתת כרת:
@3 **עוד** יתבאר על דרך אומרם ז''ל (במד''ר פי''ט) כי הגואל המקווה לעם המקוים הוא משה עצמו, ובספר הזוהר (ח''ב ק''כ) גם כן רמזוה בפסוק מה שהיה הוא שיהיה, והן הנביא משה ידע הדברים כי גלה ה' סודו אל עבדו נאמן ביתו שיבא זמן אחר שיעבור את הירדן אל הארץ וגומר, לזה דקדק בתפלתו כי מה ששואל הוא שיעבור עתה, והוא אומרו **אעברה נא** בזמן זה:
@3 **עוד** נראה לפרש אומרו **אעברה נא**, שנתכוון להשיב גם על טעם הבא בדבריהם ז''ל (רבה) למה משה מת בחוצה לארץ שהוא משום מתי מדבר להביאם לעולם הבא משל וכו' יעש''ד, לזה אמר **אעברה** פירוש דרך העברה לא להשתקע רק אעברה ברגלי וכשיגיע הזמן שיאמר לו ה' קרבו ימיך למות יבא אל המקום אשר יאמר ה' אליו:
@3 **עוד** נתכוון בלשון **אעברה**, על דרך אומרם ז''ל (כתובות קי''א.) כל ההולך ד' אמות בארץ ישראל יש לו חלק לעולם הבא, לז''א לו **אעברה נא** פירוש עתה בחיים לתועלת נפשי לתענוג המקוה שהוא עולם הבא:
@3 **אשר בעבר הירדן**. הוצרך לומר כך, לפי שיש ארץ טובה שהיא ארץ העליונה כדרך אומרו, (תהלים קט''ז) אתהלך לפני ה' בארצות החיים, והוצרך לפרט ההר הטוב והלבנון, לדבריהם ז''ל שאמרו (סוטה י''ד) שכוונת משה היה לקיים מצות הנוהגות בארץ, לזה פרט כל המקומות לומר שחפץ הוא לקיים כל המצות הנוהגות בכל המקומות. עוד נתחכם משה לומר כדברים האלה לבל יהיה מקום לה' לומר שיראה משם את הארץ ולא יצטדך לעבור, לזה פרט את כל המקומות שאין מציאות לראות כל זה מרחוק אם לא יעבור:
@4 **ויתעבר ה' וגו' ולא שמע וגו'**. כפל לומר ויתעבר ולא שמע, גם הפסיק בתיבת **למענכם**, בין מאמר ויתעבר למאמר ולא שמע שהיל''ל ויתעבר ה' בי ולא שמע אלי למענכם, גם אמר תיבת **למענכם** אחר שכבר אמר למעלה (א' ל''ז) **גם בי התאנף ה' בגללכם**, יתבאר על פי מה שפירשנו במה שאמר בעת ההיא לאמר שנתכוין להתפלל על עצמו וגם על ישראל, לזה כנגד מה שנתכוין בתפלתו. על ישראל אמר **ויתעבר ה' בי למענכם** פירוש למען מה שנוגע לכם, וכנגד מה שהתפלל על עצמו אמר **ולא שמע אלי** פירוש למה שנוגע לי, ובזה לא אמר לשון עברה כי שאלת משה על עצמו היא שאלת חכם בטענה הנשמעת כמו שכתבנו למעלה מה שאין כן ישראל שהציפו את ה' ונתחייבו כלייה ב''מ לזה אמר ויתעבר:
@4 **או** ירצה על זה הדרך **ויתעבר ה' בי** למות חוץ לארץ למענכם מטעם הידוע כדי שיעמדו עמו לעולם הבא, כאומדם ז''ל, ולזה דקדק לומר **ויתעבר** לשון עברה על דרך אומרו (צפני' א') יום עברה היום ההוא שהוא יום המיתה, ואומרו **ולא שמע אלי** שלא רצה ה' שיכנם לארץ כל עיקר, אפילו בתנאי שיצא ממנה אחר כך ויקבר במקום ההוא שבו נקבר עם מתי מדבר כמו שפירשנו למעלה במאמר אעברה נא:
@4 **ויאמר וגו' רב לך וגו' אל תוסף**. כפל לומר רב לך אל תוסף, בא להשיב לב' דברים הבאים בתפלת משה, כנגד מה שהתפלל על עצמו אמר לו **רב לך** רמז לו בתיבת רב כי כלום טעם תפלת משה לעבור אל הארץ הוא כדי לקיים מצות התלויות בארץ, לזה השיבו שאינו צריך לזה כי יש לו רב טוב אשר יתן לו ה', והוא אומרו רב לך ואינך צריך לשום תוספת זכות, וכנגד מה שהיה מתפלל על ישראל השתיקו בגערה ואמר לו אל תוסף דבר וגו':
@4 **או** נתכוון לומר על זה הדרך כי כל זכות שתגיע לבאי הארץ מן המצות התלויות בארץ יש לך חלק בכלן ומה זה הוא החלק שאתה הוא המצוה אותם לעשות, והוא אומרו **רב לך** פירוש הרבנות של קיום המצוה לך היא ואם כן יש לך חלק עם כל א' בכל מעשה אשר יעשו שם ואשר ע''כ אל תוסף דבר בדבר זה:
@4 **עוד** נתכוון במאמר **רב לך** להשיב על טענת אעברה נא שפירשנו שרצה לומר שיעבירהו מהמלכות משום מלכות יהושע, לזה אמר **רב לך** פירוש הגדולה והרבנות היא מיועדת ומיוחדת לך כל זמן שאתה בנמצא ולא אפשר לתת הגדולה לתלמידך בחיים חיותך, ומעתה אין תיקון לטעם אין מלכות נוגעת בחברתה וכו' (ברכות מח:), ולדרך זה המאמר אל תוסף צריך לעצמו ואינו מיותר:
@4 **עוד** נראה לפרש על זה הדרך רב לך לגופא, ואומרו **אל תוסף** נמשך עם מה שלאחריו שהיא מאמר עלה ראש הפסגה וגו', פירוש לפי שאמר לו ה' עלה ראש וגו' שנתקבלה חצי תפלתו שאמר ואראה את הארץ הטובה, חש ה' שיאמר משה אוסיף לשפוך שיחי וזה לך האות כי ה' שמע קולי בשיחי, לזה אמר לו אל תוסף וגו' **בדבר הזה** פירוש בדבר זה שאני אומר, והוא מה שגמר אומר **כי לא תעבור** פירוש דבר זה מוחלט הוא:
@5 **וראה בעיניך**. הוצרך לומר תיבת **בעיניך**, ומה גם אחר שאמר בסמוך שא עיניך, נתכוון לומר לו כי מה ששאל לראות על ידי הליכתו לארץ כאומרו אעברה ואראה יעשה לו ה' נם ויראה באמצעות עיניו לבד בלא הליכה כל מה ששאל לראות אחר שיעבור, והוא דבר שאין עין הזולת תוכל לראות, והוא מה שדקדק במאמר עיניך בכינוי:
@5 **עוד** ירצה לפי שימצאו חכמות שיקריבו הרחוק על ידי דבר אמצעי שמשימין אותו בין עיניהם למול מקומות הרחוקים ויקרבם ויראם כאילו הם לפניו, ולשלול דבר זה אמר ה' אליו וראה בעיניך ממש פירוש בלא אמצעות דבר אחר:
@6 **וצו את יהושע**. צריך לדעת מה היא מצוה זו, ובספרי אמרו (פנחם קל''ו) וז''ל צוהו על הגבעונים ד''א צוהו על המריבות וכו' ע''כ, ואין זה מפורש בכתוב זולת אם נאמר שהם דברי קבלה, ואפשר לומר בפשט הכתוב על פי דבריהם ז''ל שאמרו אין צו אלא מלכות דכתיב (ש''א י''ג) ויצוהו ה' לנגיד וגו', ועיין מה שפירשתי בפרשת (שמות ו' י''ג) ויצום אל בני ישראל וגו', כמו כן בא מאמר ה' כאן למשה שבחייו ימלוך יהושע על ישראל ויחזקהו במלכותו לעיני כל ישראל:
@7 **ונשב בגיא וגו'**. צריך לדעת כונת הכתוב מה בא להודיע במאמר זה, ומה קשר יש לו לא עם מה שלפניו ולא עם מה שלאחריו, ורבותינו ז''ל בספרי ישבו הכתוב והביאו רש''י ז''ל, ולדבריהם ז''ל לא נתישב כונת אומרו **ונשב** כיון שלא בא אלא להודיע מעשה פעור, גם מאמר **מול בית פעור** אין לה משמעות אם לא בא הכתוב אלא להזכיר עבודת פעור, היה לו לומר ותצמד לבעל פעור, ונראה שכונת הכתוב היא גמר ענין שהתחיל בו בתחילת הפרשה ואתחנן אל ה' וגומר, וגמר אומר שלא הועיל בתפלתו לעבור את הירדן ונשב בגיא אין ישיבה אלא עכבה עד עולם, ואומרו **בגיא** לפי שארץ ישראל גבוהה מכל הארצות דכתיב (במדבר י''ג י''ז) עלו זה בנגב, ואומרו **בית פעור** רמז א' מטעמי קבורתו שם (פדר''א פ' מ''ו) כדי שיהיה מול עון פעור לבל ירים ראש לקטרג על יש רא ל:
@8 **ועתה ישראל וגו'**. אולי שנתכוון כנגד ב' דברים שאירעו לו, אחד בענין הכאת הסלע שה' אמר לו לדבר והוא הכה וחשב לעשות המצוה בזריזות גדול. ב' בענין זמרי ששגג ולא נתאמץ לעשות דין קנאים פוגעים ולא זכר בקידוש ה' שהזמין ה' לפניו לתקן מעשה הראשון אשר לא קדש ה' כמו שפירשנו הדברים במקומן, והגם שדן לפניו פנחם השיבו (סנהדרי פב.) קריינא דאגרתא להוי פרוונקא וזכה פנחם בדבר ונטל ברית השלום שהיה מוכן למשה:
@8 **ואפשר** כי טעמו של משה הוא לפי שרפו ידיו מחיזוק ידים שעשה בראשונה, ואולי שחש כי לא אמר ה' קנאים פוגעים בו אלא אם ראהו אבל לבקש אחרים לפגוע בו לא, ונשמר וישב ולא עשה כדרך שעשה בסלע שנזדרז להכות ויצתה לו תקלה ואחר האמת שגג בזה, ולזה בא להזהירם לעם בני ישראל עם ב' הדברים שבהם שגג ונמנע מעלות אל הר ה' צבאות עיר עז לנו ונשב בגיא מול וגו', ואמר להם **ועתה ישראל שמע אל החוקים** שהם המצות שהם חוקים וזה דמיון מעשה הסלע שאמר לו ה' דבר לסלע שבו נכוה, ודבר זה יתיחס אליו חוקה, ואומרו **ואל המשפטים** כנגד המשפטים שהעריך ה' בתורתו שהם דמיון משפט בועל ארמית שקנאים פוגעים בו ששגג בו משה ומאמצעות שניהם נגזרה עליו גזירה כנזכר:
@8 **וגמר** אומר **למען תחיו ובאתם וירשתם את הארץ** ולא יקרה לכם כאשר קרה לי שאינני עובר את הירדן, וגמר אומר **לא תוסיפו** להזהירם שלא יארע להם כדרך שאירע לו, על דרך מה שאמרו בברייתא (ת''כ ר''פ אחרי) היה רבי אליעזר מושלו לרופא שנכנם אצל חולה וכו' ואחד אמר לו אל תאכל צונן ואל תשכב וכו' שלא תמות כדרך שמת פלוני זה זרזו יותר מן הראשון ע''כ, כמו כן במה שלפנינו נתכוון משה לזרז שלא יארע להם כמו שאירע לו על מה שהוסיף להכות הסלע, ואמר **לא תוסיפו** פירוש מה שאני אומר לכם שמע אל החקים וגו' למען תחיו ובאתם תנאי הוא הדבר שלא תוסיפו וגו' שאם יוסיפו כדרך שעשה הוא במעשה הסלע לא יבואו וגו' כדרך שנגזרה עליו גזירה בשביל זה:
@8 **ואומרו ולא תגרעו וגו' לשמור**, פירוש בבא לידם דבר משפט שזכר בתחילת דבריו ואל המשפטים לא יגרעו ממנו כדרך שעשה הוא בענין זמרי שנשמר מלבקש לפגוע בו וגרע המשפט, והוא אומרו **ולא תגרעו** הגם שתהיה כונתכם לשמור פירוש שהגרעון יהיה בו צד השמירה להשמר לבל יהרוג בועל הארמית:
@10 **עיניכם הרואות וגו' אחרי בעל וגו'**. פירוש אתם ראיתם החומרא שבעבודה זרה יתר על כל העבירות שאפילו אותם שלא עבדוה אלא שחשבו בלבם והלכו אחריו לעובדו הגם שלא עבדוה עדיין השמידם ה', והוא על דרך אומרו (קידושין לט:) למען תפוש ישראל וגו':
@11 **ואתם הדבקים וגו'**. צריך לדעת למה אמר **ואתם** בתוס' וא''ו כמוסיף על ענין ראשון ולא ידמו הנדבקים בה' להולכים אחרי בעל פעור, עוד אומרו **הדבקים** בה''א הידיעה ולא מצינו שקדם זכרון דביקות זה שיוצדק לומר עליו הדבקים:
@11 **ואולי** שיתבאר על דרך מה שדרשו ז''ל בסנהדרין (קח.) בפסוק ונח מצא חן בעיני ה' וז''ל ונח אפילו נח שנשתייר מהם לא היה כדאי אלא שמצא חן ע''כ, כמו כן נתכוון במאמר **ואתם** פירוש וגם אתם הייתם ראוי' להשמיד אלא לצד היותכם דבוקים פירוש נתקרבתם בתשובה ונדבקתם בה' בזה אתם חיים, ודקדק לומר **כלכם** להעיר שלא על חלק מהם הוא אומר אלא על כולם, וכן הוא אומר הכתוב בפרשת פנחס במעשה פעור (כ''ה י''א) ולא כליתי את בני ישראל בקנאתי, הא למדת שעומדים היו להשמד כולם, והגם שפינחס הוא שמנע מהם הכליון, עם כל זה מוכרח שעשו תשובה אחר כך שאם לא כן לא היה מועיל פינחס אלא לכפר למה שכבר עשוהו ולא למה שעתיד:
@11 **עוד** ירצה בתום' וא''ו לפי מה שפירשתי באומרו אשר הלך אחרי בעל וגו' שנתכוון לו' הגם שלא עבד אלא חשב בדעתו לעבוד, נתכוון בוא''ו של **ואתם** לומר תוספת בדמיון הראשון כדרך שענש ה' על המחשבה במה שלפניו הגם שלא עשו מעשה כמו כן ג''כ אתם בענין דביקותכם בה' המחשבה בזה הקב''ה מצרפה למעשה, וכן אמרו ז''ל (קידושין מ.) מחשבה טובה הקב''ה מצרפה למעשה מחשבה רעה אין הקב''ה מצרפה למעשה זולת בע''ז, ודקדק לומר **ואתם הדבקים**, יתבאר על דרך אומרם ז''ל (ברכות ז.) בפסוק (שמות ל''ג ט''ז) ונפלינו אני ועמך שבקש משה מה' שלא ישרה שכינתו על אומות העולם, ופירשנוהו שם שהכוונה הוא אפילו יכשירו מעשיהם, והוא שאמר כאן אתם פירוש אתם הם הדבקים בה' ולא עכו''ם שאם העכו''ם ירצו להדבק בה' לא יזכו לזה, ולדרך זה מאמר הדבקים הוא גזירת הדיבור גם כן למאמר אתם:
@11 **הדבקים בה' אלהיכם**. יתבאר על פי מה שכתב רמב''ם בפ''ו מהל' יסודי התורה וז''ל וז' שמות הם הוי''ה וכו' כל המוחק אפילו אות אחת מז' שמות אלו לוקה כל הנטפל לה' מלפניו מותר למוחקו וכו' מלאחריו כגון ד' של אלהיך כם של אלהיכם אינם נמחקים והרי הם כשאר אותיות של שם שהשם מקדשם ע''כ, והוא מה שנתכוון לומר להם במאמר **הדבקים בה'**, פירוש ולפי ששם זה המיוחד שם הוי''ה אין אות נדבקת ונסמכת לו מלאחריו אלא מלפניו כגון לה' בה' כה' ואותיות אלו אין בהם קדושה ומותר למוחקם ואם כן תהיה דביקות ישראל בה' בדרך זה שאין השם מקדשם, לזה גמר אומר **אלהיכם** פירוש דביקות זה שאתם דביקים בה' אינה כדביקות האותיות שמלפניו אלא כאותיות שמלאחריו שהם כם של אלהיכ' שהם קדושים כשאר האותיות של השם:
@11 **גם** רמז בתיבת **בה'** ייעוד נעים והוא שם זה אינו מקדש מלאחריו הא למדת שדביקות ישראל הוא בשמות עצמם מתאחדים אור נפשם באור שם הנכבד, וכדי שלא תבין שהכוונה הוא כאותיות הנטפלים מלפניו ואין בהם קדושה גמר אומר **אלהיכם**, אמור מעתה כי כוונת אומרו **בה'** היא ביחוד האותיות, והוא מה שאמר הכתוב (דברים ל''ב ט') כי חלק ה' עמו, הרי כי חלק א' הם ישראל משם הוי''ה ב''ה, ובזה תצדיק פירושנו זה, ואולי כי ידבר הכתוב כנגד ב' הדרגות שישנם בישראל זו למעלה מזו והבן:
@11 **עוד** נתכוין במאמר **הדבקים בה' אלהיכם** על דרך אומרם ז''ל (זוהר ח''ג רל''ח) כי העושה מצוה שורה שם הוי''ה על האבר שבו עושה המצוה, ואמרו כי מצות עשה הם רמוזים בשם הוי''ה ומצות לא תעשה רמוזים בשם אלהים, והוא אומרו כאן **ואתם הדבקים** על ידי קיום מצות עשה ולא תעשה בב' שמות אלו שם הוי''ה ואלהים כאומר בה' אלהיכם:
@11 **עוד** ירצה על זה הדרך כשאתם דבקים בה' פירוש שלבכם חפץ בו ובמצותיו בזה הוא נקרא אלהיכם ביחוד, על דרך מה שאמרו ז''ל (ילקוט ס''פ נח) בפסוק יושב תהלות ישראל שלא נתרצה ה' בכל מהלל צבא השמים עד שאמרו בתהלותיו ברוך ה' אלהי ישראל כי לא בחר שתתייחד אלהותו אלא על ישראל, ולזה תמצא שאין מתברך ולא מתהלל באלהי שמים ולא באלהי הארץ ולא באלהי מלאכים אלא אלהי ישראל:
@11 **חיים כלכם היום**. נמשכת למעלה ולמטה, נמשכת למעלה על זה הדרך אלהיכם חיים כי ה' נקרא (לקמן ה' כ''ג) אלהים חיים, ונמשכת למטה ג''כ חיים כלכם, והכוונה בשיעור הדיבור על זה הדרך להעיר שהחיים נמשכים להם ממקור החיים, והכונה בזה שזולת זה לא יקרא חיים הגם שיתנועע ויאכל וכו' שהרשעים בחייהם קרוים מתים (ברכות יח:) לצד שמקורם מקור המיתה, וזה הוא החידוש שמחדש להם משה במאמר זה שמודיעם שהם חיים ממקור החיים:
@11 **ושיעור** כוונת דברי משה הוא בב' דרכים, א' הוא על זה הדרך מצד שאתם דבקים בה' אלהיכם חיים אתם חיים כמו שכתבנו בסמוך, ב' על זה הדרך טעם שזכיתם להדבק בה' אלהיכם לפי שאתם חיים פירוש צדיקים שנשמרתם ממטעמי הרשע שהם בחינת המות ובחרת בחיים ולשניהם נתכוין הכתוב:
@11 **ואומר כלכם** נתכוין לכללות הפרטי וכללות הכללי על זה הדרך, כללות הפרטי שכל אחד מהם הי' כלו חי בלא אבר גרוע על דרך מה שדרשו בחולין (זבחים קטז.) בפסוק מכל החי הבא בהמה שחייה ראשי אבריה ואין בה מום, כמו כן מה שלפנינו היו כולם תמימים בלא מום, וכן אמרו רבותינו ז''ל (מכילתא) שכל שעמדו על הר סיני לא היו בהם סומין דכתיב וכל העם רואים וגו' ולא וכו' ע''כ, הא למדת שלא היו בהם מומין ועמדו בחזקתם, ונתכוין בין על מומי הגוף בין על מומי הנפש, וכבר העירותי שמום שבגוף יגיד על פגם הנפש כי אין מום שאין דמיונו בנפש ואשר על כן פסלו ה' לבעל מום מעל המזבח, ועיין בדברי הזוהר (ח''ג ד'), כללות הכללי שלא היה בהם אחד שאינו הגון שלא יקרא חי אלא כולם צדיקים, ואומרו **היום** לא החליט מאמר היותם חיים כולם אלא היום כי מי יאמר אשר יהיה למחר מצד מעשיהם שאדם בחירי הוא ואין אמונה בו עד יום לכתו לארץ החיים:
@17 **ואשמעם את דברי וגו' ליראה אותי כל הימים**. יתבאר על דרך אומרם ז''ל (שבת קמו.) ישראל שעמדו על הר סיני פסקה זוהמתן, ופירשתי בפרשת יתרו שפסיקת זוהמתן היתה מאמצעות גבורות דברי אלהים עד שיצתה נשמתם וזהו הסרת זוהמה מהם, והוא מאמר **ואשמיעם את דברי** פירוש עשרת הדברות שבאו בגבורות דכתיב (שמות כ' א') וידבר אלהים את כל הדברים, וטעם שעשיתי זה **ליראה אותי כל הימים** באמצעות הפסק זוהמתן מהם שהוא המונע את האדם מלירא את ה', וזה סיבה שישראל לא מרו את כבודם וסבלו כמה צרות ימים רבים אין מספר ועל משמרת יראת ה' עומדים כי פסקה זוהמתן וטבע נפשם ליראה את ה', כי כל שאין זוהמא מבדלת בינו לבין ה' מטבעו לירא ה' הנכבד ב''ה:
@19 **קול דברים אתם שומעים**. אומרו **קול דברים**, יתבאר על פי דבריהם ז''ל (שהש''ר פ' ישקני) שאמרו שכל דיבור שהיה יוצא מפי ה' היה נוצר ממנו מלאך והיה עומד על האדם ואומר לו אתה מקבלני וכו' והיה מחבקו וכו' ע''כ, וכפי זה יתבאר הכתוב על נכון **קול דברים** פירוש הדברים אשר דבר ה' שהיו נבראים מהם מלאכים קול אותם מלאכים שנקראים דברים אתם שומעים, ועיין מה שכתבתי בפרשת יתרו שלא שמעו ישראל מפי הגבורה אלא אנכי וגו' ולא יהיה לך וגו' אבל השמנה דברות הגם שיצאו כאחד יחד עשרת הדברות לא יכלו לסבול לשמוע אלא ב' והח' עמדו המלאכים שנחצבו מקולו יתברך בהם עד שחזרה נשמתם וחזרו ושמעום מפי המלאכים שהם הדברים עצמן והיתה כל מצוה ומצוה שהוא מלאך ומלאך עומד על האדם ואומר לו אתה מקבלני וכו':
@19 **ותמונה אינכם רואים וגו'**. קשה איך יוצדק לאמר על התמונה **זולתי קול** שהיא השמיעה, ולפי מה שכתבתי בפסוק שלפני זה שהמלאך שהוא הדיבור עצמו היה מדבר עם כל אחד והיו ישראל רואים אותו, וכן תמצא שאמרו רבותינו ז''ל (מכילתא) בפסוק וכל העם רואים את הקולות, ומעתה חש משה שיחשבו ח''ו כי זה הוא אלהי ישראל אשר ראו עיניהם, לזה אמר **ותמונה אינכם רואים זולתי קול** פירוש לבד הקול הוא שהייתם רואים תמונתו שהיה מדבר עמכם ואומר אתה מקבלני וכו':
@28 **וה' התאנף וגו' לבלתי וגו' ולבלתי וגו'**. חזר לומר עוד מאמר זה ולא הספיק מה שאמר בפרשת דברים דכתיב (א' ל''ז) גם בי התאנף וגו', גם כפל לו' **לבלתי** ב' פעמים, לומר גזירה אחרת שנגזרה עליו מלבד שימות במדבר עוד גזר עליו שלא יעלו עצמותיו להקבר בארץ כדרך שעשה הוא לעצמות יוסף וכדרך שעשו כל ישראל לשאר השבטים (ירושלמי סוטה פ''א ה''י), והוא אומרו **לבלתי עברי** פירוש בחיים **ולבלתי בא** פירוש לאחר מיתה אל הארץ הטובה, והוא מה שאמר עוד בסמוך **אנכי מת** וגו' **אינני עובר את הירדן** פירוש בין קודם מיתה בין לאחר מיתה, וגמר אומר כנגד ישראל **אתם עוברים** ולא לאחר מיתה לבד אלא אפילו בחיים והוא אומרו **וירשתם** וגו', ודיבר בדרך לא זו אף זו. ואומרו **על דבריכם** כאומרם ז''ל (דכ''ר ב') משל למי שנאבדו לו מעות ופיזר ביניהם דינר זהב וכו', כמו כן עת שיעמוד משה יעמדו עמו כל דור המדבר הוא הוציאם ממצרים הוא יוציאם מהמדבר ויביאם לעולם הבא לעתיד לבא עם הצדיקים ע''כ, והוא אומרו על דבריכם שזולת טעם סיבתם להביאם לעולם הבא לא היה נשבע לבל יכנסו עצמותיו של משה לארץ הטובה:
@36 **ובקשתם וגו' בכל לבבך וגו' בצר לך וגו'**. ב' כתובים הבאים אלו צריכין ביאור דע כי יש ב' הדרגות תשובה, יש תשובה שישראל עושים מעצמן שיכירו חיובם עם הבורא ויכופו יצרם, ויש תשובה שעושים על ידי יסורין אשר יצר להם האויב ויצעקו מכאב לב, וכנגד ב' הדרגות דיבר משה אל כל ישראל, כנגד העושה תשובה הגם שלא שמע קול נוגש אמר **ובקשתם משם את ה' אלהיך** שיתעוררו הלבבות לחיבת אלהיהם, ומצאת, והגם שיש בידך עבירות חמורות כאמור בסמוך ועבדתם שם אלהים אחרים וגו' אף על פי כן פטורים אתם מהיסורין ודי לכם התשובה, והטעם כי תדרשנו בכל לבבך שתשובה כזו היא תשובה שלימה בכל לב ובכל נפש:
@36 **וכנגד** תשובה הבאה מצד היסורין אמר **בצר לך ומצאוך** וגו' **ושבת** וגו' פירוש מחמת היסורין אשר יצר לך אויבך, וכאן לא הזכיר בכל לבבך וגו' כי באמצעות היסורין הוא שב, ומה שחסר לשבים מחמת יסורין בבחינה הדרגת התשובה משלימין אותו בבחינת היסורין עצמן שעברו עליהם כי היסורין ממרקין העונות ומטהרין את הנפש, ומה שחסר לכת הראשונה מצד שלא עברו עליהם יסורין משלימין אותו בבחינת מעלת התשובה, וכפי זה מאמר בצר לך נמשך עם מה שלפניו וזה שיעורו **ובקשתם** וגומר **ומצאת** והטעם **כי תדרשנו** וגו' **או בצר לך** וגו' **ושבת** הגם שלא תהיה בכל לבבך וגו', ונתן הכתוב טעם לקבלת ה' תשובה שלימה לבדה בלא יסורין או תשובה שאינה שלימה על ידי יסורין כי אל רחום ה' אלהיך:
@36 **עוד** יתבארו הכתובים על זה הדרך **ובקשתם משם** פירוש וכשתהיו בין האומות שם תבקשוהו ותתפללו אליו לדברים הצריכים לכם לחיותכם, ואינו מדבר בבקשת הגאולה, **ומצאת** שימצא לכם שאם לא כן יאבדו ב''מ, ואמר לשון יחיד לומר שלא לכולם ימצא כשיקראוהו בארץ העמים אלא ליחידי סגולה, והטעם כי **תדרשנו** וגו' פירוש צריך מבקש ה' התעצמות גדול ואולי ישיגו הבקשה בסדר זה יחידי עם:
@36 **ואומרו בצר לך** כתוב זה מדבר בהבטחת הגאולה כי בצר לעם ישראל שהוא זמן הגלות עוד לו שימצאוהו כל הדברים האלה האמורים בסמוך שהם השמדה מן האדמה והפצה בין האומות והמעטה שישארו מתי מספר זה יהיה באחרית הימים והם חבלי משיח, ולא יהיה להם כל הצרות בתמידות בזמנים ארוכים אלא באחרית הימים, ומבטיחם שיעורר ה' לבבם אז לשוב בתשובה, והוא אומרו **ושבת עד ה'**, ונתן טעם להבטחה זו כי אל רחום ה' אלהיך לא ירפך וגו' ויחזק לבך לשוב וגו':
@36 **ואולי** שזו היא טענת מיכאל לפני ה' שהביא בזוהר חדש (דף ל') שהרי באו אחרית הימים ומצאו אותם כל הדברים ולמה לא יעורר ה' לבם לשוב, ופירשתי המאמר במקום אחר, ועינינו לה' צופיות לפתוח אוצר רוח טהרה לפקוח עינים עורות ולהטות לבבות עם ה' להכיר נעימות עריבות ידידותו:
@43 **מן השמים וגו'**. כוונת הכתוב הוא, לפי מה שפירשתי בפרשת יתרו בפסוק וידבר אלהים (כ' א') והעירותי עליו למעלה בפסוק (י''ב) ותמונה אינכם רואים וגו' יתישב על נכון, כי עשרת הדברים באו להם בב' הדרגות על זה הדרך, ב' דברות שהם אנכי ולא יהיה לך הגיעו הדברים לישראל מה' להם בכח הדברים ובתגבורתם, וכנגדם אמר **מן השמים השמיעך את קולו**, והטעם **ליסרך** פירוש למרק זוהמתך זה היה סיבה להעברת מהם כל זוהמא כמו שכתבנו כמה פעמים, וח' דברות תשלום העשרה שמעו אותם מהדברים עצמן שיצאו מהאדון ברוך הוא, וכנגדם אמר **ועל הארץ הראך את אשו** הוא ראיית הקולות שהם להבות אש שנחצבו בדבר ה', וראו אותם ישראל דכתיב (יתרו כ' ט''ו) וכל העם רואים את הקולות, וכמו שפירוש בפסוק (י''ב) ותמונה וגו', ואומרו **ודבריו שמעת מתוך האש** לדברינו יבא על נכון כי הח' דברות שמעו אותם מתוך האש האמורה שהוא מלאך אש לוהט וכמו שפירשתי בפסוק (י''ב) ותמונה:
@46 **וידעת היום**. צריך לדעת מה ידיעת יום מימים מה ישיב אל לבו, ואולי שנתכוון להערות הצריכין להכניע היצר השוכן בלב האדם:
@46 **א')** על דרך אומרם ז''ל (ברכות ה'.) אם פגע בך מנוול זה וכו' ואם לאו יזכור לו יום המיתה ובזה יהיה נכנע לבבו, והוא אומרו **וידעת** יתן בדעתו היום הידוע שהוא יום המיתה ובזה **והשבות אל לבבך** להשיבו אל דרך הטוב והישר, ודקדק לומר **לבבך** ל' רבים לרמוז לב' יצרים יצר הטוב ויצר הרע:
@46 **ב')** על דרך אומרם ז''ל (סוכה נ''ב.) שלעתיד לבא יביא הקב''ה את השטן ושוחטו לעיני כל ישראל, וצוה משה שיתן האדם בידיעתו היום ההוא הגדול שבו ישלוף ה' חרבו וישחט ס''מ הרשע ובזה ישיב אל לבבו לדרך הישר כי יכנע השטן לפניו:
@46 **ג')** עוד ירצה שיזכור לו היום הגדול שהוא יום הדין מה יעשה כי יקום אל וכי יפקוד מה ישיבנו וכמה תגדל חרפתו לפני קהל ועדה עליונים ותחתונים ובזה והשבות וגו':
@46 **ד')** על דרך אומרם ז''ל (ב''ב פ''ד.) למה החמה בבוקר פניה אדומים וכו' לפי שעוברת על פתחה של גיהנם וכו', והוא אומר **וידעת** תן לבך לדעת מעשה היום ותראה הכרה בשמש כי יש דין לעוברי רצונו ובזה תשיב אל לבבך וגו':
@46 **ה')** על דרך אומרם אנשי אמת שונים בש''ע כי בחינת הקדושה תקרא יום ובחינת הזרות תקרא לילה ועל ידי מעשה אדם יכחד מבחינת יום ויהיה חלקו במדת לילה, ולזה התפלל דוד ואמר מפחד בלילות, והוא אומרו **וידעת היום** פירוש השתדל לדעת מדה זו שנקראת היום ובזה אתה מעצמך תטה לבבך לדרך הנכון:
@46 **ו')** על דרך אומרם ז''ל בספר הזוהר (ח''ג קעח.) וז''ל מאן אינון מארי חושבנא אינון דבכל לילה עכדין חושבנא בנפשייהו במה דעבדין בההוא יומא ומתקנין ארחייהו וכו' ע''כ, והנה אם האדם עושה כדבר הזה דבר יום ביומו ירגיש במעשיו הרעים וישוב על השגגות ויתודה על העבר, וזולת זה לצד מיעוט הרגשתו בהם יתמיד עשות כהם וגדולים מהם וגם כי ישוב לא יזכור את אשר עברוהו להתוודות עליהם, ולזה צוה משה במאמר **וידעת היום** פירוש שבכל יום ידע מעשהו של אותו יום והוא דרך מארי דחושבנא ובזה **והשבות אל לבבך** שלא יתמיד בהם ואין צריך לומר שלא יוסיף להרע:
@46 **ז')** על דרך אומרם בספר הזוהר (ח''א רלג:) כי יום שהנפש באה מעולם העליון משביעה ה' על התורה ומתרה בה בעונשין מרובין וביעודים מרובים אם תטיב ועיין בספר הזוהר, וכנגד יום זה אמר **וידעת היום** פירוש היום שנסע שיזכור יום נסיעת נפשו מעולם העליון בכמה התראות, וזה ישיב אל לבו וכו':
@46 **ח')** על דרך אומרם ז''ל (חגיגה י''כ:) כי עולם הזה יקרא לילה ועולם העליון יקרא יום, והנה לצד שיראה האדם דברים מנוגדי' בעה''ז צדיק ורע לו רשע וטוב לו לאין חקר יטהו לבבו מבחור בטוב הנצחי ויראהו הרשעים בעולם הזה שמסריחין ומרויחין ויאמר אליו הלא תראה כי טוב הוא, לזה אמר **וידעת היום** שהוא עולם המתיחס אליו יום **והשבות אל לבבך** תשובה ניצחת כי ה' בוחר הקיום לידידיו ומשלם לשונאיו וכו':
@46 **ט')** על דרך אומרם ז''ל (שבת פ''ח.) בפסוק (בראשית א' ל''א) ויהי ערב וגו' יום הששי, שהתנה ה' עם מעשה בראשית על יום מתן תורה וכו', והוא מה שרמז באומרו **וידעת היום** פירוש היום הנכבד שנגלה על הר סיני מה נורא מעשיו ושעליו בא התנאי עם העולם ובזה תשיב לבבך לדרך התורה, ולדרך זה או' **כי ה' הוא האלהים** נמשך עם מה שלמעלה והשבות אל לבבך שעל ידי היום ההוא הוכר לכל העולם כי אין אלהים זולתו בשמים וגו' ועל הארץ, וכאומרם ז''ל (מכילתא פ' אנכי ה') בפסוק (ישעי' מ''ח) לא מראש בסתר דברתי:
@46 **י')** יתבאר על דרך אומרם ז''ל (שמו''ד פ' כ''ה) שקול שבת כנגד כל התורה כולה, והנה לפי שיבא היצר ויאמר לאדם מה כחך כי תיחל לקיים כל התורה כלה שהיא שלימות האדם, ומה גם אדם שעברוהו רעות רבות ירחיקהו היצר מה תוכל לתקן את אשר פעלו ידיך מהרעות, לזה אמר משה **וידעת היום** אותו שכתוב בו היום שהוא השבת דכתיב (שמות ט''ז כ''ה) כי שבת היום תן דעתך עליו ובו תשיב אל לבבך כי הוא שקול כנגד כל התורה, וזה יועיל לסתור ב' טענות בין לתקן מה שעברוהו מהמרדים בין להשלמת הנפש, שעל ידי שמירתו הרי הוא כאלו קיים תרי''ג מצות:
@47 **נותן לך כל הימים**. פירוש לפי שאמר להם למען תאריך ימים על האדמה חש משה שיאמרו שהכונה היא שעל ידי מעשיהם הוא שה' מאריך ימיהם על האדמה, וממוצא דבר אתה למד שהגביל ה' ימי נתינת הארץ כדרך שהגביל חיי האדם דכתיב (איוב י''ד) אם חרוצים ימיו והבטיחם להאריך ימיהם כשילכו בדרך ישר, לזה גמר אומר וביאר **אשר ה' אלהיך נותן לך כל הימים** פירוש כי מתנת ה' היא לעולמי עד לא לזמן מוגבל, ומעתה אומרו **ולמען תאריך ימים** פירוש שלא ימותו בה בקצרות שנים על דרך אומרו (עקב י''א כ''א) למען ירבו ימיכם וגו', ואומרו **כל הימים** היא העמדת הארץ ביד ישראל:
@53 **אשר הכה משה וגו' בצאתם ממצרים**. קשה והלא בשנת הארבעים הכה משה ארץ סיחון, ואולי שנתכוין לומר כי מעת יציאתם ממצרים היה מוכן לפניהם להכותו שאם לא היה מעשה המרגלים היו מכים אותו בשנה שניה לצאתם מארץ מצרים:
@53 **עוד** נתכוין לומר כי מעת שיצאו ישראל ממצרים אימות מות נפלו עליו מהם והיה מוכה ועומד על דרך אומרם ז''ל (ב''ר פרק פ') שמסורת בידם וכו', ולזה סמך מאמר **בצאתם** למאמר ההכאה ואחר כך אמר ויירשו את ארצו להעירך כדברינו:
@57 **ויקרא משה**. אולי לפי שירשו כל הארצות ההם היו ישראל מפוזרים בכל המקומות ההם לזה הוצרך לקרות לכלן, או אפשר שעד עתה היה מדבר עם האנשים וכשרצה לומר עשרת הדברות קרא גם לנשים והטף כמעמד הר סיני כאומרו כל ישראל:
@58 ה' **אלהינו כרת וגו'**. הנה לא ביאר משה מה ברית הוא זה אם ברית שכרתו ישראל לקיים תורת ה' דכתיב (שמות כ''ד) הנה דם הברית אשר כרת ה' עמכם על כל הדברים, או ברית שכרת ה' לישראל שלא יחליפם באומה אחרת דכתיב (שמות ל''ד) הנה אנכי כורת ברית נגד כל עמך וגו' ופירשו ז''ל שכרת להם ברית על זאת שלא תשרה שכינתו על האומות, והדעת מכרעת שעל ברית זה הוא אומר, והוא מה שרמז באומרו ה' **אלהינו כרת עמנו** פירוש על שיהיה אלהינו ולא לזולתינו כרת עמנו ברית ועליו חוזר מאמר הברית הזאת שאמר אח''כ, וכפ''ז כוונת המאמר לשבח ישראל המושג מה' להם, ועיין בפ' שא ח ''ז:
@59 **לא את אבתינו כרת וגו'**. רש''י פירוש בלבד, וקשה אם לזה נתכוין הכתוב לא היה צריך לומר שכבר אמר כרת עמנו, ולפי מה שפירשתי בפסוק ה' אלהינו וגו' שחוזר לברית שלא ישרה שכינתו על האומות יתבאר על זה הדרך, **לא את אבותינו כרת** הברית כל עיקר שלא מצינו שנשבע להאבות שלא ישרה שכינתו על אומה אחרת, וכפי זה לא הספיק במאמר כרת עמנו שיכול להתפרש גם עמהם ואינו לשלול האבות, לזה חזר לומר לא את אבותינו, והכונה בזה שזכו ישראל דברים שלא הובטחו בהם האבות:
@59 **כלנו חיים**. קשה והלא כל אותן שכרת ה' עמהם הברית אינם חיים שמתו במדבר, גם לא כל אותם שעמהם היה מדבר היו אז שהרי נולדו כמה וכמה בל''ח שנה שנתעכבו במדבר, ויש ליישב שאמר על החלק אלא שהדבר דחוק, עוד מה בא ללמדנו בתיבת **כלנו חיים** אין בה חידוש, ואולי יש לומר שנתכוון לומר שכלם נשארו חיים הגם שדבר ה' עמהם פנים בפנים וגו' מתוך האש ולא מת א' מהם, והוא מה שאמרו לבסוף מי כל בשר אשר שמע קול אלהים חיים מדבר מתוך האש כמונו ויחי, וכפי זה מאמר כלנו חיים נמשך עם מה שלאחריו ולא עם מה שלפניו:
@61 **אנכי וגו'**. פירוש חלק דבר ה' עמכם פנים בפנים וחלק שהוא לבד מעשרת הדברים דברתי אני בשליחות, וטעם שלא דבר ה' עמכם הכל פנים בפנים כי יראתם וגו':
@61 **ולא עליתם בהר לאמר**. פירוש ואסר לכם ה' עלות בהר בשביל לאמר אנכי ה' וגו':
@68 **שמור את יום וגו'**. רבותינו ז''ל אמרו (ר''ה כ''ז.) זכור ושמור בדיבור א' נאמרו, ולדבריהם אפשר לו' כי אומרו **כאשר צוך** להעירם על שמור שנצטוו גם עליה מפי ה' יום המעמד, והכוונה בשמור אמרו ז''ל (מכילתא פסוק זכור) לשמור מלאחריו, ויש לדעת למה לא נאמרה שם שמור עם זכור, ואולי שנתכוון להפרידם לבל יחשבו שמאמר שמור הוא על זמן שבא עליו מאמר זכור שהוא מלפניו על זה הדרך שיזכור לשמור השבת, ובמה שהפרידם העיר שהם ב' מצות אחת בהכנסה ואחת ביציאה, ואולי כי לעולם לא אמר ה' אלא זכור אלא שאחת נשמעת מחברתה למביני דעת, וכשאמר ה' זכור נתכוון שיזכור בנתינת דעת עליו לבל יהיה לו שגיון בו וממוצא דבר אתה למד שגם על לאחריו הוא מצוה, והוא מה שפירוש משה במה שאמר שמור שגם הוא נכללת בזכור, וזה כתבתי בדרך אפשר:
@71 **וזכרת וגו'**. הם דברי משה, והכוונה כי יום השבת יש בו גם כן הערה לאדם לזכור יציאת מצרים, כשהוא שובת בלא שעבוד ירגיש כי ה' הוא המניח לעמו מכל צריהם ויתן לבו לקבל גזירות המוציא מעבדות, ורבותינו ז''ל אמרו (פסחים קי''ז:) מכאן שצריך להזכיר בקידוש היום יציאת מצרים:
@71 **ואם** תאמר למה השמיט טעם השבת שאמר ה' בדברות ראשונו' שהוא כי ששת ימים וגו', טעם זה הוא טעם המצוה מעיקרא לא טעם החיוב ומשה אמר טעם חיוב אמונת טעם המצוה, על פי מה שאמרו רבותינו ז''ל וכתבנוהו במקום אחר כי יציאת מצרים גלתה אמונת בריאת העולם (ש''ר י''ב) והוא מה שרשם באומרו **וזכרת** וגו' **ויוציאך** וגו' **ביד חזקה ובזרוע נטויה** ושם ראית כי הוא אדון הכל ובזה יתאמת לך טעם האמור בדברות ראשונות כי ששת ימים וגו':
@75 **את הדברים וגו'**. ולא אמר כל, כי יש מהדברים האמורים שלא דברם ה' כגון מאמר כאשר צוך גם מאמר וזכרת:
@80 **ושמענו ועשינו**. אומרו **ושמענו**, לפי שהם אמרו למשה להשיב לה' על מאמר בעבור ישמע העם בדברי עמך (שמות י''ט ט') שרצונם לשמוע מפי ה' ולא מפי תלמיד, לזה עתה חזרו ואמרו סתירה לדבריהם הראשונים ושמענו וגו', ואומרו **ועשינו**, קיימו וקבלו היהודים לעשות כל דבריו כאלו שמעו מפי השכינה:
@81 **הטיבו כל אשר דברו**. פירוש שקבלו על עצמם לעשות דברי הנביא ולהצדיקו, ועל זה גמר אומר מי יתן והיה וגו', ואמרו ז''ל (ע''ז ה') ששגג משה שלא אמר לו תן אתה שאלו היה אומר כן לא היו מהרהרין אחר משה, לא בשלוח מרגלים ולא במחלוקת קרח:
@82 **ליראה אותי ולשמור וגו'**. טעם שלא סמך לכלול השמירה בכלל מאמר ליראה, אולי כי לפי שמצד היראה יצא פרט א' רע שזה היה סיבה שעשו ישראל את העגל כשראו כי בושש משה נפל עליהם אימתה ופחד כיון שאין משה שיהיה שליח לדבר עמהם ישוב ה' לדבר עמהם כבראשונה, לזה מהרו לעשות העגל לחושבם שיהיה לאמצעי וידבר אליהם את דברי ה', ותמצא שאמרו ז''ל (תנחומא פ' תשא) שהעגל היה מדבר ממש וטעו בו לאמצעי, לזה דקדק ה' במאמרו ואמר **ליראה אותי ולשמור** מצותי שתהיה היראה להם גם כן לשמור ולא ישגו בהם מצד הירא ה:
@82 **למען ייטב וגו'**. פירוש כי אומרו מי יתן וגו' לא לצד המועיל לאומרו אלא לאהבת הטוב להנאמר עליו:
@84 **ואתה פה וגו'**. פירוש לפי שלא עשו ישראל למשה שליח לקבל פקודי ה' עד עתה, לזה ה' גמר בעדם וקבעו לשליח ואמר לו ואתה פה וגו' **ואדברה אליך את כל המצוה** וגו', ואולי שנתכוין לומר שבהגיע המצוה מה' למשה כאילו נתקבלה לישראל שהרי עשאוהו שליח וכדין שליח האשה לקבל קדושיה שכיון שקבלם השליח כאילו באו ליד האשה כי ידו כידה, כמו כן כשיקבל משה המצוה כאילו קבלוה ישראל, והוא אומרו **ואדברה אליך** ובהגיע הדבר אליך אתה תודיע להם ועשו אותה, והוא אומרו תלמדם ועשו:
@86 **בכל הדרך וגו' למען תחיון וטוב לכם והארכתם וגו'**. פירוש תחיון אריכות ימים בעולם הזה, ואומרו **וטוב לכם** טובת עולם הבא, ואומרו **והארכתם** וגו' שלא יגלו ישראל מעל הארץ לעולם, ולסברת רבי יעקב (קידושין ל''ט:) שאמר שכר מצוה בעולם הזה ליכא, נראה שיודה ר' יעקב במי שהוא צדיק גמור ושמר כל התורה שיזכה גם בעולם הזה, ולא אמר ר' יעקב אלא באדם שרובו זכיות, וכן תמצא שאמרו שם בקידושין כשהקשה מאותה ברייתא שאמרה כל מי שרובו זכיות מריעין לו וכו' והעמיד בש''ם כרבי יעקב:
@86 **וממנה** יש לנו לדון ממה שאמר כל מי שרובו זכיות הא למדת דוקא מי שיש בידו עבירות אלא שרבו זכיותיו הוא שאומד עליו מריעין לו וכו' אבל מי שכולו זכיות יודה כי יטיב לו ה' גם בעולם הזה, והוא מה שאומר **בכל הדרך אשר צוה** וגו' דקדק לומר **בכל** להעיר שמדבר במי ששומר הכל ולאיש כזה ישנו בעולם הבא כאומרו למען תחיון וטוב וגו', גם ישנו בעולם הזה והוא אומרו **והארכתם ימים בארץ אשר תירשון** ולא אמר והארכתם ימים סתם שנפרש שנתכוין לעולם שכלו ארוך:
@90 **שמע ישראל ה' אלהינו וגו'**. טעם כפל ה' ב' פעמים ולא הספיק לומר על זה הדרך ה' אלהינו אחד, נתכוון לב' הדרגות שיש לה', האחד שהוא אלהינו, והב' שהוא אחד, והכוונה בזה כי אנו מקבלין אלהותו יתברך עלינו למה שממנו הגם שאילו היה במציאות שהיו אלהות הרבה אין אנו בוחרים אלא בשם זה הוי''ה הוא אלהינו, ובזה נכלל כמה פרטים, א' אהבת הטוב, אהבת המועיל, אהבת הערב, ועוד לו שהוא אחד ואין זולתו אלוה בעולם וטעם זה גם כן יספיק להתחייב להשתעבד לו ולמצותיו הגם שהיה במציאות שלא היו הטעמים שמצדם בחרנוהו לאלוה:
@90 **נמצינו** אומרים שבאחד מב' הטעמים יספיק להשתעבד למאמריו ולמצותיו, אשר על כן אמר ה' **אלהינו ה' אחד** בב' חלוקות שכל א' כדאי לעצמו, ואם היה אומר הכתוב ה' אלהינו אחד היה בנשמע כי מה שהם מקבלין אלהותו עליהם הוא להיותו אחד ואין עוד מלבדו, יתחייב העבד לעבוד את רבו ואין מנוס ממנו לרצונו ושלא לרצונו, ולא כן אנו עם אלהינו שאנו חפצים באלהותו אהבת הטוב במה שהוא טוב נוסף על היותו אחד ומיוחד:
@91 **ואהבת**. אמר בתוספת וא''ו, לומר מלבד מצות שמע ישראל שהוא קבלת עול מלכות שמים היא מצות אהבת ה'. עוד ירצה להעיר להקודם לאהבה על דרך אומרם ז''ל (זוהר ח''ג נ''ו) אין אדם משיג גדר האהבה עד שתקדים בו היראה, והוא אומרו **ואהבת** מלבד גדר היראה, ואומרו **את ה'** פירוש על ידי האהבה אדם מתדבק בה' והוא אומרו את ה':
@91 **עוד** ירצה שעל ידי אהבת ה' ישיג מדרגה זו שיהיה ה' מיחד שמו עליו ביחוד כדרך אומרו (בראשית כ''ח י''ג) אלהי אברהם אלהי יצחק, ופירוש שכל אחד ראוי בפני עצמו שיתיחד שם אלהותו עליו, ותמצא שאברהם ביאר בו הכתוב שהיה אהוב דכתיב (ישעי' מ''א) זרע אברהם אוהבי, וכמו כן רמז הכתוב כאן שכל שאהוב ה' יקרא ה' אלוהו ביחוד, ותיבת ה' נמשכת לפניה ולאחריה:
@91 **עוד** ירצה לעורר לב איש ישראל לאהבת ה' על דרך אומרם ז''ל (ילקוט ס''פ נח) בפסוק יושב תהלות ישראל שלא בחר ה' מכל התהלות זולת כשהללוהו ואמרו לפניו ברוך ה' אלהי ישראל אז ישב על כסא מלכות עולם, והוא אומרו **ואהבת את ה'** לטעם זה שלא בחר להיות אלא אלהיך, ובהעיר האדם לבו לפרטי' כאלו תתנתק נפשו ותתר ממקומה בהתעוררות נפלא ורם באהבת הנאהב יתעלה רום תפארת כבודו:
@91 **עוד** אולי שנתכוון לעורר לב האדם בג' מיני אהבה שישנם בהכרה לנבראים, והם אהבת הטוב, אהבת הערב, אהבת המועיל, לזה בא דבר ה' לשלשתם, **ואהבת את ה'** בשם זה העיר הלב לבחינת אהבת הטוב במה שהוא טוב הרמוז בשם כאומרו (תהלים קמ''ה) טוב ה' לכל, גם בחשק הערב בסוד (תהלים ל''ד) טעמו וראו כי טוב ה', כי כל הנפש אשר יוכיח שם זה למולה אין עריבות בכל הנבראים שיכנם אליו בערך הנשתוו, וזה לך האות אומרו (שה''ש ה') נפשי יצאה בדברו, גם תשכיל בפסוק (במדבר ל''ג), ע''פ ה', כי תתנתק הנפש מהגוף ולא תרגיש בפרידה להפלגת הרגש הערב מהטוב, הרי שמענו אהבת הטוב ואהבת הערב מתיבת ה', ואהבת המועיל רמזה באומרו אלהיך על דרך אומרו (תהלים כ''ב) יושב תהלות כמ''ש בסמוך, ובזה נכלל גם כן אהבת המועיל כי בזה הרווחנו עולם ומלואו כמאמר שלמה (קהלת י''ב) כי זה כל האדם כל העולם כלו לא נברא אלא לצוות לזה (שבת ל:):
@91 **בכל לבבך ובכל וגו'**. רבותינו ז''ל אמרו (ספרי) בזה מה שאמרו יעויין שם דבריהם, ונראה שנתכוון ה' במאמר זה להסיר טינא מלב אוהביו, והוא שאמרו רבותינו ז''ל (מוע''ק כ''ח.) בני חיי ומזוני לאו בזכותא תליא מלתא אלא במזלא ע''כ, והנה ג' דברים אלו הם כללות חשק האדם וחפצו בעולם, החיים, והבנים, והמזונות, והחסר אחד מהנה ב''מ יקרא מת, ושלשתם אינם תלויים להשיגם באמצעות עבודת ה' ואהבתו, וזה יסובב ההרחקה מאוהבי ה', ומה גם בהתקבץ להאוהב שנים מהם חוסר הבנים והעוני יתחמץ לבבו בקרבו, והגם שיתחזק עם לבבו לבבו לא ישמע לו כי המורגש אליו ירחיקנו משמוע לאהוב:
@91 **לזה** בא דבר ה' וצוה לו על הדבר הזה שיעריך אהבת ה' בלבו בג' דברים הגם שיטלם ממנו, כנגד הבנים אמר **בכל לבבך** על דרך אומרו (בראשית כ''ב ב') את בנך וגו' אשר אהבת וגומר והאהבה כזו היא אהבה הממלאת לב אדם וחשקו, וכנגד חיי אמר **ובכל נפשך**, וכנגד מזוני אמר **ובכל מאודך**, שיעריך בדעתו שלשתם יחד בה', כי הוא טוב לישראל מעשרה בנים, ושלחן גבוה עליון הוא מאוד כמאמר התנא (אבות פ''ו) ששולחנך גדול משולחנם, והחיים ממנו תוצאות חיים, ואף כי אחרי מות הצדיק יקרא חי כאומרו (ש''ב כ''ג) ובניהו בן יהוידע בן איש חי הרי שאפילו אחר מיתה יקרא חי (ברכות י''ח.):
@91 **או** יאמר על זה הדרך כי בא הכתוב לשער שיעור האהבה שמחויב כל איש ישראל לאהוב הבורא, ואמר שהוא בשיעור ההרגש אשר יבא בלב האדם בעת אשר תשיג ידו לג' דברים כא', כמו שתאמר אדם שהיה חשוך בנים ועני ונטה למות ובא נביא בדבר ה' ובשרו כי יקום מחליו גם אמר אליו הנה אשתך הרה ויולדת בן וכי ריוח גדול נזדמן לו להעשיר בהם, אדם כזה מה מאוד יפליא אהבת האדון באין שיעור ותהיה האהבה מורגשת בלבו בחשק מופלא על אשר הטיב עמו כמה מעלות טובות, כמו כן יצו ה' על כל איש ישראל עשות באהבתו תמיד, והוא אומרו **ואהבת את ה'** וגו' **בכל לבבך** פירוש כאילו נתן לך כל מחסורך בכל לבבך שהם הבנים, ודקדק לו' בכל להעיר דמיון המשל שהוא חסר מהבנים ויתנם ה' לו, וכמו כן **ובכל נפשך** שנתן לך נפשך אחר הגיעך לשערי מות, **ובכל מאודך** כאילו נתן לך כל ממונך שאתה חפץ ואמר כל להעיר דמיון המשל:
@91 **והנה** המשכיל בענין חשק ה' כל זה דבר קל הוא בערך מה שהנפש חושקת בבורא, והמשלתי דבר זה לאדם גדול ומופלא בנכסים שרצה ללכת למקום רחוק לצד סכנת מקום שהיה בו ואסף כל נכסיו בקנית מרגליות גדולה באלף אלפי דינרי זהב ושם לדרך פעמיו לעיר רחוקה אשר שם נכון לבו בטוח בממונו והונו וקודם שהגיע לעיר אשר פנה בדעתו ללכת שמה כלתה צידתו ואין דינר בכיסו והיה מסתפק בדלות ובעוני גדול ושפלות רב כי אפס כסף, והנה זה האיש הגם שהוא מתהלך בדוחק וצער עם כל זה לבו שמח וכליותיו עליצים כי רב אונו והונו ויצא ממקום המסתכן ובא יבא ברנה נושא האבן גדולה יקרת הערך, כן הדבר הזה אדם שזכה בדביקותו יתברך ואהבתו ובו קבץ כל ממונו והונו ויבז בעיניו קנות דבר בעולם הזה לצד סכנת המקום נוסף על מיעוט שוויו ולקח לו ה' לאלהים אין לך קניה בעולם כקנין זה למעלה מהאבן יקרה שבמשל כי מי ידמה לו ומי ישוה לו, ואדם כזה לו יהיה שיהיה דחוק ומצטער בימים מועטים אלה לו בעה''ז נכון לבו בטוח בה' אור עולם וישמח לבו ויגל כבודו, ובהגיע למחוז חפצו שהוא עולם הקיים והבטוח הנה שכרו אתו, ומעתה חיבת הקודש הוא היוצר ודבקותו בו הלא הוא בניו וחייו וממונו וביתר שאת:
@92 **והיו הדברים וגו'**. לפי מה שפירשתי בפסוק ואהבת את ה', ירצה לומר כי ישים הדברים האמורים רטייה על לבו בראות אחת מג' אלה, כי יראה חסרון הלחם לאיש צדיק, או חסרון החיים, או חסרון הבנים, ידע כי אין הדבר לצד חסרון ההשג מה שהשיג זולתו, אלא שדברים אלו חשובים כאין נגדו:
@92 **עוד** ירצה ללמד בני ישראל דרך שיתקבלו הדברים אצלם לאהוב ה', כי האהבה אינה מעשה שיכריח האדם רצונו לעשות מצות המלך אלא הוא דבר שתלוי בלב וכל שהלב לא ירגיש דבר שיפעול בו החשק אינו אוהב הגם שיכריחנו בכל מין הכרח, לזה באה העצה מאל יועץ ואמר **והיו הדברים הא לה** וגו' **על לבבך**, פירוש כשיתמיד שימת הדברים על לבו יולד בלבו חשק תאוה הרוחניות וירוץ לבו לאהבת ה' בכל אשר ציוהו, ודבר זה אנחנו יתמי דיתמי אנו מרגישים כי רבה תאוה בלבנו וחשק אלהי עולם יותר מכל הון עולם וכבוד מלכות וכל ערב נרגש לנמבזה ונמם בערך חלק המועט המושג מהרגש הוית הדברים על לבנו אשרינו מה טוב חלקנו, וכבר העירותי בדברים אלו בכמה מקומות:
@92 **עוד** נתכוון הכתוב לשלשה הדרגות שהם כולל גדרי האהבה, האחד כנגד ההרגש הוא חמדת הלב, וא' כנגד הצורך שהוא מזון המחיה את האדם, ואחד בגדר השיעור עד כמה צריך לצאת ידי חובת האהבה, כנגד גדר ההרגש אמר **בכל לבבך**, הנה הגם שיתאוה האדם לאכול או להון לא יהיה כל כך עוצם הערבות הגם שהנפש חפיצה לאכול יכול אדם למשול ברוחו למנוע עצמו מהדבר בנקל, מה שאין כן כשנכנס בלבו חמדת הלב ויתאוה לאשה יפה ומה גם כי יתרבה חשקה בלבבו יפעיל בו ההרגש עד שאינו יכול למשול ברוחו להטות לבו ויכוף אותו לעשות מה שאין רצונו עשות, צא ולמד כמה נתעצם יוסף הצדיק לכוף חמדת הלב במעשה אשת פוטיפר ושכרו יגיד לו:
@92 **וכנגד** גדר זה אמר הקב''ה **ואהבת את ה' אלהיך בכל לבבך** שישתדל להכנים אהבת ה' בלבבו וילהיבנו באהבתו עד גדר שישיג הרגש בלבו ככל שיעור שיכול הלב להרגיש בו, ולזה דקדק לומר **בכל**, לפי שהלב יחמוד בכל אשה וביותר בנאה וביותר בכלילת יופי וביותר במי שאין למעלה ממנה, וחייב הכתוב שתהיה הרגשת הלב באהבתו יתברך בגדר הגדול שאין למעלה ממנו, ודבר זה הוא דבר שהטועמו ידע מהותו וערבה לו טעימתו אין שיעור לה, ולפי שגדר זה מציאותו הוא על ידי התעוררות כדרך אומרם (במד''ד פ''ו) עין רואה ולב חומד, אבל זולת זה לא יתעורר הלב מעצמו לחמוד, לזה העיר ה' במאמר ב' בגדר הצורך ואמר **ובכל נפשך** שהם דברים שהנפש צריכה להם כגון אכילה ושתיה וכדומה שהאדם מתעורר מעצמו להם בלא אמצעות דבר, כמו כן תהיה אהבת ה', והוא אומרו **בכל נפשך** שמטבעו תהיה אהבת ה' כמאכל ומשקה, והנה שני הדרגות אלו ישנם בגדר המצטער והמתגדר, שהמאכל אחרי אוכלו ואחרי שתו יחדל ממנו החפץ בו, וכמו כן תאות לבו אחר גמר מעשה דרך גבר בעלמה (משלי ז') ישתנה הדבר אצלו עד אחר זמן, לזה בא דבר ה' בהדרגה ג' בגדר השיעור ואמר **ובכל מאדך** פירוש בכל ממון שאתה חפץ בו, וכשם שהממון אמר הכתוב (קהלת ה') אוהב כסף לא ישבע כסף, כי כשאדם מגיע לקנות קנין עצום אז יתעצם חפצו לחפוץ בהוני הונות והולכת תאותו וגדלה, וכמו כן יצו ה' באהבתו שלא תשתער ותוגבל וכשיגיע גדר א' תגדל בו האהבה לגדר עליון מזה, ולדרך זה שיעור אומרו **מאדך** לא מה שקנה אלא שחפץ לקנות, ובזה יתישב גם כן מה שהיה קשה בו אם אתה אומר מה שקנית אם כן אין מצוה זו שוה בכל שהרי אדם עני אינו בן מצוה זו, גם באנשי ממון לא תהיה להם המצוה בהשואה, מה שאין כן במצות לבבך ונפשך שהכל שוים בו, ולפי דרכנו יבא על נכון:
@111 **וצדקה תהיה לנו וגו'**. צריך לדעת הכונה במאמר **צדקה**, ורמב''ן פירש שחוזר אל שכר המצות כי יהיה בתורת צדקה מה' כי עבדים אנחנו וחייבים לעבוד ואין לנו דין שכר ע''כ, ואין הכתוב מיושב על נכון לדבריו ז''ל, עוד צריך לדעת כוונת אומרו **לפני ה' כאשר ציונו** וגו':
@111 **אכן** הכוונה היא לפי שיש ב' הדרגות בעבודת ה', א' היא עבודה מיראה, וזה היא חיוב על כל הנבראים שכל עבד ירא מרבו על דרך אומרו (מלאכי א') אם אדונים אני איה מוראי, והוא מאמר הכתוב (עקב י' י''ב) מה ה' אלהיך שואל מעמך כ''א ליראה. ב' היא עבודה מאהבה, והיא מצוה רבה ועצומה, אבל אין חיובה לצד היות האדם עבד שיהיה אוהב, די שלא ישנא ויעבוד הצריך, וזה הוא דבר שחייב העבד לרבו, וכנגדו רבו חייב לזונו ולפרנסו כיד רבו, כנגד חיוב המוטל לצד היותו עבד אמר הכתוב שקודם לזה **ויצונו ה' ליראה את ה'**, וגמר אומר **לטוב לנו** וגו' **לחיותינו** וגו', פירוש מצות ה' באה בחיוב ליראה כמשפט עבד למלכו, וגם על ה' להטיב כיד המלך לפרנסה ולכלכלה לחיותינו כי חייב האדון בפרנסת עבדו:
@111 **ואומרו כהיום הזה** פירוש כסדר שהוא עושה היום הזה שהוא זן ומפרנס מוריד המן וגו' ומכסה כאומרם ז''ל (מד''ר תבא פ''ז) שהיתה כסותם גדלה עמהם כחומט והעננים מגהצים הבגדים, וכנגד עבודה מאהבה אמר זה אינו בחיוב העבד אלא בדרך **צדקה תהיה לנו כי נשמור** וגו' לפני ה', רשם בזה תכלית האהבה על דרך אומרם ז''ל (חובת הלבבות שער אהבת ה' פ''א) וז''ל האהבה היא כלות הנפש ונטותה אל הבורא, וזו היא דביקות הנפש לפני אור הנערב הוא ה' אלהינו, ואומרו **כאשר ציונו** פירוש לא לצד שום פניה אלא לעשות מצות ה' כדרך אומרו (תהלים מ') לעשות רצונך אלהי חפצתי, שזה הוא עשות המצוה באהבה שלמה ועיין מה שפירשתי בפרשת אחרי מות בפסוק כמעשה ארץ מצרים וגו', ודבר זה בו יצטדק אדם ויקו לשכר גם כפי הדין, והגם שכפי האמת עלינו לשלם שכר לאלהינו ברוך הוא שהטעימנו עריבות נעימות מתיקות אהבתו בלבנו מתוקים וערבים לאין תכלית, אלא שיטול אדם שכר על התעצמותו עד שהשיג טעם בחיים:
@111 **עוד** רמז הכתוב רמז נעלם שבאמצעות שמירת המצות תהיה לנו חלקנו שכינתו יתברך הנקראת צדקה (תיקוני זוהר תכ''א) והבן:
@118 **כי אתם המעט**. לא הספיק מאמר לא מרובכם, שאז ישנו בנשמע שאינם מרובים אלא שוים תלמוד לומר אתם המעט:
@120 **ולשומרי מצותיו לאלף דור**. רבותינו ז''ל אמרו (סוטה לא.) שלעושים מיראה לאלף דור ולעושים מאהבה אלפים כאומרו (שמות כ' ו') ועושה חסד לאלפים לאוהבי וגו', ונראה כי לא כפל לבד יגיד אלפים כי בודאי שעושה מאהבה אין קץ לשכר מעשיו, ולאלפים האמור באוהביו לשון רבים יכולנו לומר עד מאה אלף, וטעם שאמר סתם כי אין שיעור שוה לאהבה ויש בין אוהב לאוהב כפלי כפלים אלא קטן שבאוהבים כפלים כגדול שביראים:
@121 **ומשלם לשונאיו וגו'**. קשה למה אמר **שונאיו** לשון רבים וגמר אמר **פניו להאבידו** לשון יחיד, ואולי כי טעם אומרו לשון רבים כי לא ישלם לרשע אל פניו אלא כשיראה כי לא הוא בלבד שונא אלא גם הבאים ממנו כיוצא בו שבזה אין לו תקוה, והוא אומרו **ומשלם לשונאיו** לשון רבים, אבל אם לא יהיה שונא אלא הוא וזרעו הבא ממנו לא יהיה שונא ברא מזכה אבא ולא ישלם לו להאבידו:
@121 **וגמר** אומר בלשון יחיד כי ביחיד מדבר הכתוב אלא שהעירך בדבר האמור במה שאמר שונאיו ל' רבים, וחזר לומר **לא יאחר** וגו' פירוש ואם אין הרשע בא ברבים אלא הוא לבד שונא ולא הבאים אחריו יתחכם ה' עמו באופן אחר ולא יאחר לו בעולם הזה לשלם לו עונשו כדי שלא ירשיע עוד ותאבד תקותו אלא ימהר לשלם לו מיתה שהוא חייב בה או יסורין כיון שיש לו תקוה שיזכה באמצעות בנו:
@121 **ואומרו אל פניו** על דרך אומרם ז''ל (ירושלמי ע''ז פ''ג) שהצדיקים מטעימם ה' סמוך למיתתם מעין עולמם ונפשם שבע' וישנים מתוך שמחה, והרשעים מראה להם הרעה המזומנת להם קודם צאתם מהעולם (אסתר רבה פ' ותמאן המלכה ושתי), והוא אומרו **לא יאחר לשונאו אל פניו** פירוש בעולם הזה קודם שיטמנו פניו בעפר יראהו תשלומיו ולא יאחר עד בואו שמה:
@121 **חסלת פרשת ואתחנן**
